export const materialKnowledgeSources = Object.freeze(Object.fromEntries(sourceSpecs.map(([id,title,organization,url,kind,description,section]) => ['mat-'+id,{title,organization,url,kind,description,...(section?{section}:{}),reviewed}])));
const ids = (...values) => values.flat().map(value => value.startsWith('mat-')?value:'mat-'+value);
const paragraph = (text,...sources) => ({text,sources:ids(...sources)});
const section = (id,title,text,...sources) => ({id,title,paragraphs:[paragraph(text,...sources)]});
const maker = (name,offering,note,...sources) => ({name,offering,note,sources:ids(...sources)});
const alternative = (name,description,tradeoff,...sources) => ({name,description,tradeoff,sources:ids(...sources)});
const term = (term,definition) => ({term,definition});
function article(key,summary,sections,suppliers,alternatives,inspection,terms,relatedIds=[],reading=[]) {
 const sourceIds=[...new Set([...sections.flatMap(s=>s.paragraphs.flatMap(p=>p.sources)),...suppliers.flatMap(s=>s.sources),...alternatives.flatMap(s=>s.sources),...ids(reading)])];
 return {key,summary,sections,suppliers,alternatives,inspection,terms,relatedIds,sourceIds};
}
const topics = {};

topics.battery = article('battery-enclosure',
 'A battery enclosure turns a collection of cells into a mountable spacecraft assembly. It supports the cells, provides a controlled heat path and organizes electrical connections; the housing is only one part of a working battery.',[
 section('purpose','What the enclosure is for','During eclipse the battery supplies power that the solar array cannot provide. Its enclosure must keep the cell assembly attached to the spacecraft during launch and preserve its electrical isolation throughout charging and discharging. Cell capacity belongs to the electrochemistry; pack capacity, operating limits and service life also depend on interconnections, monitoring and temperature. A convincing exterior model therefore does not establish a complete battery design.','power','saft'),
 section('operation','How cells, heat and structure meet','Every charging or discharging cell produces some heat. A pack needs a deliberate route from the cells, through holders or interface materials, to its mounting surface and onward to the thermal system. Uneven contact can leave one cell warmer than its neighbors even if the box exterior looks cool. Cell retention, allowances for dimensional change, insulation and any vent routing must be developed together. NASA’s Orion battery work is a useful example of that coupled engineering.','orion-battery'),
 section('engineering','What engineers specify','A housing drawing normally defines mounting datums, fasteners, connector access, electrical bonding and the thermal interface. Machined aluminum offers precise pockets and a conductive base; sheet construction can reduce machining but adds seams and joining details. Anodizing can provide a surface treatment, while selected bonding or heat-transfer lands may need another finish. Black appearance alone says neither how well the case radiates heat nor how much protection it gives the cells.','anodize','structures')],
 [maker('Saft','VES16 cell and battery reference','Use the cycling presentation to understand the cell technology behind the battery benchmark; it does not specify these modeled enclosures.','saft'),maker('EaglePicher','Space COTS battery families','Examples of complete packaged batteries, useful for comparing the boundary between cells, controls and mechanical packaging.','eagle')],
 [alternative('Modular battery packs','Separate packs can simplify accommodation and replacement during integration.','More housings, connectors and monitoring interfaces must be coordinated.','eagle'),alternative('Shared cold base with cell modules','Modules can share a strong thermal and structural mounting surface.','Thermal coupling and electrical isolation become important at the common interface.','orion-battery')],
 ['Follow the housing mounting face toward the core structure. Cell holders, internal monitoring, vents and detailed thermal contacts are not established by the exterior geometry.'],
 [term('Pack','Cells and the mechanical, electrical and monitoring provisions that make them usable together.'),term('Thermal interface','The contact through which heat passes between joined parts.')],['flight:02.02','flight:02.03','flight:03.02']);

topics.boards = article('accelerator-boards',
 'The accelerator board is where electrical power becomes computation and heat. Packaged processors, memory, power conversion and fast interconnects need a physical carrier that survives launch and moves heat to the cooling hardware.',[
 section('purpose','What is inside a compute tray','A processor package is not a complete computer. It needs power at several voltages, access to memory, control signals and a route for incoming and outgoing data. A board integrates those connections and supports the packages mechanically. The workbench’s compute benchmark describes useful computational capability; it does not establish which terrestrial accelerator board, memory population or component layout would be flown.','a100'),
 section('operation','Why the board is an engineered stack','Conductive traces and planes connect components through an insulating laminate. Plane arrangement influences return-current paths, noise and heat spreading; connectors must preserve signal quality as well as fit mechanically. Most processor heat needs a short path from the package to the cold plate, rather than a long journey through the board. Vibration support, component mass and thermal expansion all affect how the assembly is mounted.','workmanship','act-chassis'),
 section('engineering','Fabrication and verification choices','Rigid boards suit compact equipment; rigid-flex constructions can remove some harness connectors at the cost of more demanding fabrication and inspection. Laminate selection depends on dielectric behavior, temperature, dimensional stability and environment. Solder joints, staking and cleanliness matter as much as a visually intricate board texture. Radiation behavior must be assessed for the actual devices and mission; a board maker’s space experience cannot make an arbitrary commercial processor radiation tolerant.','ttm','workmanship')],
 [maker('NVIDIA','A100 accelerator','A computing reference, not a flight-qualified board selection or the layout reproduced in the viewer.','a100'),maker('TTM Technologies','Commercial-space circuit fabrication','A relevant manufacturing example for boards and interconnects; component selection and assembly qualification remain separate.','ttm')],
 [alternative('Replaceable accelerator cards','Cards permit modular assembly and individual replacement before launch.','Their sockets and retainers add interfaces and must carry launch loads.','act-chassis'),alternative('Integrated custom processor board','One board can match the enclosure, memory and power distribution closely.','Custom design and verification replace the convenience of an existing module.','ttm')],
 ['Look for the relationship between device locations, tray supports and cooling surfaces. Printed traces and package detail are illustrative, not a vendor schematic.'],
 [term('PCB','Printed circuit board: patterned conductors supported by insulating layers.'),term('Return path','The route current takes back to its source, important to signal integrity.')],['flight:01.01','flight:01.01.01','flight:01.02']);

topics.chassis = article('compute-tray-chassis',
 'Tray carriers hold the computing assemblies in position and connect them to the spacecraft’s structure and thermal system. Their design determines how a board can be installed, supported, cooled and inspected.',[
 section('purpose','More than a shelf','A carrier must react the inertia of its boards during launch without relying on electrical connectors as structural supports. It also preserves clearances around neighboring equipment and gives technicians repeatable installation references. A collection of identical trays can simplify assembly, but small differences in cable access or heat load can still require different local interfaces. The carrier should be considered together with its mounting rails and the surrounding frame.','structures'),
 section('operation','The load path and the heat path','Mechanical loads pass from components to their board supports, then through the tray into the core structure. Heat may follow a related route through edge rails or a separate route from packages into a cold plate. A well-conducting chassis is useful only when its contacts are effective: a narrow or poorly clamped joint can dominate the temperature rise. Conduction-cooled electronics provide a helpful real example of card-edge retention and heat transfer working together.','act-chassis'),
 section('engineering','Manufacturing and assembly decisions','Machined carriers can place mounting faces and board guides precisely; folded sheet or modular extrusions may be economical for repetitive geometry. Designers trade stiffness, mass, access and ease of joining rather than simply making walls thicker. Surface treatment must respect electrical bonding and thermal contacts. Cable bends, tool access and the order in which trays are installed deserve attention before a detailed design freezes the space around them.','anodize','structures')],
 [maker('Advanced Cooling Technologies','Conduction-cooled chassis','A useful packaging and heat-path comparison; its illustrated chassis is not the selected flight tray.','act-chassis'),maker('Beyond Gravity','Spacecraft structural products','Examples of panels, inserts and support structures around mounted equipment.','beyond-structures')],
 [alternative('Independent cold-plate trays','Each tray can have a defined thermal and mechanical interface.','More plumbing or thermal joints may be needed between trays.','thermal'),alternative('Shared card cage','Several cards share guide rails, enclosure and backplane.','Common interfaces constrain card formats and can couple servicing or thermal behavior.','act-chassis')],
 ['Trace a tray’s support into the larger frame, and compare its cooling contact with its mechanical attachments. Anodized surface detail does not define the underlying alloy.'],
 [term('Datum','A reference surface or axis used to locate parts consistently.'),term('Card cage','A structure that guides and retains multiple electronic cards.')],['flight:01.02','flight:01.01.02','flight:07.01']);

topics.storage = article('storage-carrier-enclosure',
 'The storage enclosure packages the devices that retain data between processing and transmission. Its job is to support, cool and connect the storage assembly; it does not determine how many bytes the selected architecture can reliably keep.',[
 section('purpose','Where data waits','A spacecraft may generate or process data faster than a link can continuously deliver it. Storage bridges those gaps, so its hardware must remain accessible to the compute and communications system through defined interfaces. The carrier protects the physical installation of drives, memory boards or recording electronics. Data integrity also depends on controller behavior, error detection and recovery, which are separate from the shape or finish of the enclosure.','storage','beyond-electronics'),
 section('operation','Making a storage module usable in vacuum','Electrical losses in memory and controllers become heat that must reach a mounting surface. A terrestrial drive shell designed around airflow is therefore not automatically a spacecraft package. Conductive supports and thermal interfaces connect the active devices to the housing, while retainers keep their mass from loading connectors during vibration. The enclosure must allow appropriate connector mating and cable restraint without obstructing the heat path.','act-chassis'),
 section('engineering','Choosing the carrier architecture','A modular carrier permits prelaunch exchange of a storage assembly and can reuse a standard mechanical interface. A custom enclosure may fit awkward space or provide a shorter thermal path, but it requires its own mechanical and electrical verification. Material choice, fastener placement and surface finish should support those goals. Adding wall thickness or a dark coating does not by itself demonstrate radiation tolerance, reliable data retention or adequate cooling.','structures','anodize')],
 [maker('Curtiss-Wright','FSM-C flash storage carrier','A real rugged, conduction-cooled storage-carrier comparison. Its product environment and interfaces are not a flight selection for this site.','storage'),maker('Moog','Integrated Avionics Unit','A spacecraft example of modular electronic packaging; useful for comparing where storage may sit within a larger data-handling unit.','iau')],
 [alternative('Standalone storage enclosure','Separates storage installation and interfaces from the processor trays.','Additional housing, cabling and thermal contacts consume accommodation space.','storage'),alternative('Storage on a processor or avionics card','Can shorten internal data connections and consolidate packaging.','Replacement and failure isolation become tied to the host assembly.','iau')],
 ['Identify the carrier boundary and mounting direction. Individual memory devices, redundancy, capacity and error-correction circuitry are not inferred from exterior detail.'],
 [term('Carrier','The mechanical assembly that holds a device and presents its installation interfaces.'),term('Data integrity','Preserving the correctness and recoverability of stored information.')],['flight:01.03','flight:01.01','flight:05.03']);

topics.network = article('network-switch-enclosure',
 'A network enclosure carries the electronics that move data among compute trays, storage and communications terminals. It is the physical meeting point between high-speed connections, electrical power, heat rejection and spacecraft mounting.',[
 section('purpose','Connecting the computing system','A collection of processors becomes useful only when data can reach the right destination. Switch or fabric electronics route that traffic, while the enclosure organizes their connectors and supports the boards behind them. A payload fabric optimized for throughput may have different requirements from the spacecraft’s command network. Naming a box a switch does not establish its protocol, port count, timing behavior or redundancy architecture.','beyond-electronics'),
 section('operation','Signals still need a physical installation','Fast electrical links depend on controlled signal and return paths from board to connector to cable. Cable shields and equipment bonding help define the electromagnetic environment, while connector retention and bend clearance preserve the installation during launch. Optical interconnects exchange some electrical concerns for fiber routing and optical-interface cleanliness. In either case, switch electronics dissipate heat that needs a conductive path out of the box.','harness','act-chassis'),
 section('engineering','Packaging the fabric','A central switch can concentrate connectors in one accessible location, but may create a busy cable junction. Distributed modules shorten some routes while adding boxes and interfaces. A machined enclosure can incorporate board guides and a conductive base; seams, lids and connector panels still need deliberate bonding and assembly provisions. The correct choice follows actual data flows and thermal loads, not the number of decorative ports shown on a model.','structures','workmanship')],
 [maker('Beyond Gravity','Onboard data-network electronics','A spacecraft supplier comparison for network hardware; this does not specify the payload fabric used here.','beyond-electronics'),maker('Glenair','SpaceWire cable construction','An actual cable example for studying layered interconnects, not a declaration that this fabric uses SpaceWire.','harness')],
 [alternative('Central switch enclosure','Consolidates routing and simplifies a recognizable network boundary.','Cable concentration and shared-equipment dependencies need evaluation.','beyond-electronics'),alternative('Distributed switching','Places switching closer to payload nodes.','Adds power, thermal and management interfaces across the spacecraft.','beyond-electronics')],
 ['Follow the enclosure toward compute and storage neighbors. The visible connector arrangement is an accommodation illustration, not a protocol diagram.'],
 [term('Fabric','The interconnection system through which computing nodes exchange data.'),term('Signal integrity','Preserving a signal’s intended electrical behavior across an interconnect.')],['flight:01.04','flight:01.01','flight:01.03','flight:07.05']);

topics.pcdu = article('pcdu-converter-enclosure',
 'The power-electronics enclosure houses circuits that regulate, convert, switch and distribute electrical energy. Its mechanical design matters because substantial currents and local heat losses must coexist with low-level control signals.',[
 section('purpose','Where spacecraft power is organized','Solar arrays and batteries do not automatically provide every load with its required electrical supply. Conditioning electronics control the power bus, while distribution electronics connect and protect individual consumers. Some architectures combine these functions in one PCDU; others distribute conversion nearer the loads. The enclosure creates a serviceable physical boundary around those functions and connects the unit to the spacecraft’s structure and cooling system.','airbus-power','beyond-power'),
 section('operation','Heat, current and isolation','Switching devices, magnetic components and conductors have electrical losses, even in an efficient converter. Their heat must reach a baseplate without compromising insulation between circuits or the intended electrical bond to the chassis. Bus conductors carry bulk current; signal connectors carry commands and measurements. Keeping those paths organized helps manage noise, voltage drop and installation errors. A dark external finish does not replace an engineered internal heat path.','busbars','act-chassis'),
 section('engineering','Designing the box around the circuits','Modular card packaging supports different channel populations, while a custom baseplate can place high-loss devices near the thermal interface. Designers consider connector access, creepage and clearance appropriate to voltage and environment, fault-current paths, and how lids or panels are removed during integration. Converter efficiency and protected-output ratings belong to the selected circuitry and verification program, not to the rendering’s apparent enclosure size.','workmanship','airbus-power')],
 [maker('Airbus','EVO, MEGA and other PCDU families','Actual power-unit examples for comparing modular packaging and functions; none is established as the modeled unit.','airbus-power'),maker('Beyond Gravity','cPCDU and cPDU','Examples that distinguish conditioning from distribution and protected output channels.','beyond-power')],
 [alternative('Centralized PCDU','Provides a common location for bus management and protected outputs.','Harness routing and shared-unit dependencies require careful architecture.','beyond-power'),alternative('Distributed converters','Places voltage conversion close to loads.','More local electronics must be supported, cooled and commanded.','airbus-power')],
 ['Compare the housing with the bus-conductor allocation and its mounting face. Internal semiconductor layout and insulation distances are not resolved by the model.'],
 [term('PCDU','Power conditioning and distribution unit.'),term('Baseplate','A mounting surface that can also carry heat out of an electronics unit.')],['flight:02.03','flight:02.03.02','flight:02.02','flight:01.01']);

topics.avionics = article('flight-avionics-enclosure',
 'The avionics enclosure packages the spacecraft’s command, monitoring and control electronics. It is the physical home for functions that keep the vehicle operating, distinct from the computing payload’s customer workloads.',[
 section('purpose','The spacecraft’s control equipment','Flight avionics accept commands, collect telemetry and coordinate subsystem operation. Depending on the architecture, processing, power interfaces and input/output cards may share a box or be spread across several units. The enclosure preserves their mounting and connection interfaces through launch and thermal cycling. It is also an integration boundary: technicians can test the assembled unit before connecting it to the rest of the spacecraft.','iau'),
 section('operation','Cards, connectors and a controlled environment','Boards need support, electrical power and a route for heat to escape. Card guides or retainers can provide both restraint and part of the conductive cooling path. The enclosure and its bonds influence electromagnetic compatibility, but they are only part of that system; cable shielding and return paths also matter. Fault tolerance, watchdog behavior and radiation response depend on the actual electronics and software, not on a metal case alone.','act-chassis','harness'),
 section('engineering','Why packaging is a system decision','A modular unit can accommodate different interfaces without changing every mechanical feature. A dedicated custom housing may reduce wasted volume or improve a critical heat path. Designers must preserve test access, connector keying, grounding intent and the ability to assemble cards without damaging adjacent hardware. An anodized finish needs compatible thermal and electrical contact lands. The workbench’s housing does not resolve a particular backplane, processor or redundancy implementation.','anodize','workmanship')],
 [maker('Moog','Integrated Avionics Unit','A real spacecraft packaging example that combines modular avionics functions; it is a comparison, not the installed unit.','iau'),maker('Beyond Gravity','Computer and data-handling products','A second spacecraft-specific reference for understanding where an avionics enclosure fits in the control system.','beyond-electronics')],
 [alternative('Integrated avionics unit','Combines several spacecraft-control functions within a coordinated package.','Internal interfaces and common resources become part of the unit architecture.','iau'),alternative('Separate control boxes','Allows individual functions to have distinct packaging and thermal interfaces.','Additional harness, mounts and connectors consume mass and volume.','beyond-electronics')],
 ['Locate avionics relative to harness routes and the supporting frame. Exterior fasteners or panel lines do not identify a flown avionics product.'],
 [term('Telemetry','Measurements and status sent from the spacecraft to operators.'),term('Backplane','A shared electrical interface connecting multiple electronic cards.')],['flight:08.01','flight:07.05','flight:02.03','flight:04.03']);

function solarCells(record) {
 const silicon=record.materialId==='pv-silicon';
 return article(silicon?'silicon-cell-assembly':'multijunction-cell-assembly',
  `${silicon?'Silicon':'Multijunction'} photovoltaic cells are the active electrical surface of the solar blanket. Cell packages, interconnects and protective layers must function together while the blanket is stowed, deployed and repeatedly heated and cooled.`,[
  section('purpose','Turning illuminated area into power','A cell converts part of the sunlight reaching its semiconductor into electrical energy. Cells are connected into strings and circuits so the array can supply useful voltage and current to the power system. The active semiconductor area is only part of the blanket: gaps, wiring, support layers and edge details also occupy space. Array performance therefore depends on accommodation and operating conditions as well as the chosen cell technology.','esa-cell','power'),
  section('operation','What this cell technology changes',silicon?'A silicon cell uses silicon as its light-absorbing semiconductor. Its electrical behavior changes with temperature, illumination and radiation exposure, so beginning-of-life efficiency is not a complete mission power budget. Cell interconnects must carry current while tolerating motion between adjacent cells. Bypass arrangements can limit the consequences of an obstructed or underperforming cell group; the appropriate circuit depends on the full string design.':'A multijunction cell stacks semiconductor junctions that respond to different parts of the solar spectrum. This can extract more useful power from a given illuminated area than a single-junction approach under appropriate conditions. The stack still needs current collection, protective coverglass and mechanical support. The modeled blue-violet appearance does not identify a particular junction stack, efficiency, radiation performance or supplier product.','spectrolab','sharp'),
  section('engineering','Engineering a deployable cell assembly','Cell thickness, adhesive, coverglass and interconnect flexibility influence how a blanket can bend or roll. A flexible supporting film does not make a brittle cell infinitely flexible: local strain and packaging geometry matter. Designers compare deployed power against stowed volume, mass, manufacturing yield and electrical losses. Inspecting the front surface helps explain those interfaces, while detailed thermal, radiation and deployment testing establishes whether a particular assembly is suitable.','rosa','esa-cell')],
  [maker('Sharp','Silicon and compound-semiconductor space cells','A real product family for comparing cell technologies; this does not establish the supplier of the modeled blanket.','sharp'),maker('Spectrolab','Multijunction cells and CIC assemblies','A cell-interconnect-coverglass offering illustrating the assembled product boundary.','spectrolab')],
  [alternative(silicon?'Multijunction cells':'Silicon cells',silicon?'Can reduce the active area required for a specified power target.':'Offer a different cost, fabrication and power-density trade.', 'The complete comparison includes radiation degradation, temperature, packaging and procurement, not efficiency alone.','sharp','spectrolab'),alternative('Rigid-panel cell mounting','Supports cells on a relatively stiff substrate.','Stowage and deployment geometry differ from a flexible blanket.','rosa')],
  ['Compare the segmented active surface with the rear support. Cell sizes, printed contacts and surface coloration are illustrative rather than a supplier fabrication drawing.'],
  [term('CIC','Cell-interconnect-coverglass assembly.'),term('String','A connected group of cells arranged to provide a useful electrical output.')],['flight:02.01','flight:02.01.02','flight:02.01.03','flight:02.03']);
}

topics.coverglass = article('solar-cell-coverglass',
 'Coverglass is the thin transparent protective layer over a solar cell. It must pass useful sunlight while helping the fragile semiconductor survive the space environment, making optical performance and mechanical packaging inseparable.',[
 section('purpose','Protecting without blocking useful light','A solar cell needs exposure to the Sun, yet direct exposure also brings energetic particles and surface-environment challenges. Coverglass adds a protective optical barrier while allowing the wavelengths needed by the cell to reach it. It is normally part of a cell assembly, not a second opaque solar panel. Its contribution must be considered alongside the cell, adhesive, coatings and mission environment.','esa-cell'),
 section('operation','A transparent layer has several interfaces','Light encounters the front surface, the glass and the bonded interface before reaching the semiconductor. Reflections and absorption reduce the light available for electrical conversion, so coating and bonding choices matter. Thickness can improve protection but adds mass and may change handling and strain. On a flexible blanket, each small glass-covered cell must remain compatible with the local bending and spacing of the array assembly.','spectrolab','rosa'),
 section('engineering','Choosing a complete optical package','The appropriate glass composition, thickness, coating and adhesive depend on the cell technology, expected radiation exposure and thermal cycle. Engineers also consider dimensional tolerances, edge damage, contamination and the electrical behavior of exposed surfaces. A generic transparent rendering cannot establish any of these specifications. Supplier CIC data are useful because they show that the purchased item can include interconnects and a protective optical stack rather than a bare semiconductor alone.','spectrolab','sharp')],
 [maker('Spectrolab','Cell-interconnect-coverglass assemblies','Useful for studying how protective glass is integrated with a purchased cell assembly; no specific CIC is selected here.','spectrolab'),maker('Sharp','Space-cell assembly examples','A second primary reference for comparing cell technology and packaging, rather than choosing coverglass by appearance.','sharp')],
 [alternative('Thicker protective glass','May suit a different environmental protection requirement.','Adds mass and affects cell-assembly mechanics and optical transmission.','esa-cell'),alternative('Different coating or bonding stack','Can tune transmission and environmental behavior for the selected cell.','Compatibility must be demonstrated for the complete assembly.','spectrolab')],
 ['The viewer represents coverglass within the photovoltaic face. There is no separate opaque panel to isolate, and visible reflections do not specify an optical coating.'],
 [term('Antireflection coating','A surface coating designed to reduce reflected light over a specified wavelength range.'),term('Optical transmission','The fraction of incident light that passes through a material or assembly.')],['flight:02.01.01','flight:02.01.03']);

topics.backing = article('solar-blanket-backing',
 'The blanket backing supports the cell assembly while allowing the array to be packaged for deployment. Its inactive rear surface still matters mechanically, thermally and electrically even though it produces no solar power.',[
 section('purpose','Holding the active surface together','Individual cells and interconnects need a supporting architecture that preserves spacing and carries them through handling, launch and deployment. The backing provides part of that support and can contribute electrical insulation. It also creates a rear surface exposed to a different combination of sunlight, Earth radiation and spacecraft radiation than the front. Treating the array as only its blue cell face misses those physical functions.','rosa','sheldahl'),
 section('operation','Flexibility with controlled strain','A thin film can bend readily, but a blanket is a layered assembly containing less flexible cells and local reinforcements. Bending concentrates strain around thickness changes, attachments and interconnects. Tension and edge support help maintain the deployed shape, while stowage radius constrains how the assembly is packed. The backing and the deployable booms must therefore be designed together; a material described as flexible does not establish a viable rollout mechanism.','rosa'),
 section('engineering','Film, reinforcement and surface choices','Polyimide film is a relevant support-material class, but film grade and thickness are only the beginning of a specification. Adhesives, local reinforcement, conductive grounding provisions and protection from the orbital environment must match the complete blanket. An amber rear appearance is not evidence that every area has identical thermal properties. A manufacturer’s film handbook is a useful starting point for options; it is not a released solar-array laminate schedule.','sheldahl','thermal')],
 [maker('Sheldahl','Space films and coated materials','A real source of material options and property data for flexible assemblies; this is not the blanket fabricator selection.','sheldahl'),maker('Redwire','Deployable-array architecture reference','The ODC paper provides context for large flexible solar-array systems rather than a complete backing manufacturing drawing.','redwire')],
 [alternative('Reinforced flexible blanket','Local reinforcement can control load transfer at supports and edges.','Extra layers change folding, mass and local stiffness.','rosa'),alternative('Rigid panel substrate','Provides a more stable mounting surface for cells.','It needs a different stowage and deployment strategy.','structures')],
 ['Rotate to the inactive rear face and compare its continuity with the segmented cells on the front. Film grain and seams do not define the actual laminate or reinforcement.'],
 [term('Laminate','A bonded stack of layers that work together.'),term('Bend radius','The radius of curvature imposed on a flexible assembly.')],['flight:02.01.01','flight:02.01.04','flight:07.04']);

topics.boom = article('deployable-array-composite-boom',
 'A deployable boom carries the solar blanket away from the core and supports its deployed shape. Composite construction can combine low mass with tailored stiffness, but the stored and deployed configurations impose very different demands.',[
 section('purpose','Creating a large array from a small package','An array that fits inside a launch vehicle may need to span many times its stowed dimensions in orbit. Booms provide the structural reach and guide the blanket into its deployed configuration. They must carry attachment loads without excessively distorting the active surface, and their motion must coexist with harnesses and nearby structures. The useful part is the complete deployment system, not an isolated long beam.','rosa','structures'),
 section('operation','Why a composite boom can change shape','Fiber direction and laminate construction influence how a composite member bends, twists and recovers after stowage. Some rollout architectures use stored elastic energy in flattened or coiled booms; NASA’s ROSA demonstration is a useful example. Other systems use different drives and restraints. A common visual resemblance does not establish the same deployment force, speed, laminate or release mechanism for the workbench’s scaled array.','rosa'),
 section('engineering','What a dark woven surface cannot tell you','The selected fibers, resin, ply sequence and joints determine structural behavior, not the rendered weave. Designers assess launch restraint, deployment repeatability, local buckling, thermal distortion and the stiffness of the deployed array. Boom attachments are especially important because concentrated loads must enter a thin composite member without damaging it. The electrically and thermally active blanket also influences the structural design through its mass and attachment pattern.','structures','redwire')],
 [maker('Redwire','ROSA-class deployable-array reference','A relevant system-level comparison for composite booms and flexible blankets, not proof of a particular laminate in this model.','redwire','rosa'),maker('Beyond Gravity','Spacecraft structural products','Useful for comparing composite and metal structural families and their interfaces.','beyond-structures')],
 [alternative('Hinged rigid-panel array','Uses panel hinges to unfold a stiff array.','The stowed package, number of joints and deployment kinematics differ.','structures'),alternative('Motor-driven extendable support','Can control extension through a dedicated drive architecture.','Adds mechanism, power and control interfaces that require their own design.','sada')],
 ['Compare stowed and deployed positions where animation is available. Fiber texture is illustrative; it is not a map of the load-bearing plies.'],
 [term('Ply','One oriented layer in a composite laminate.'),term('Buckling','A loss of structural stability under compressive or combined loading.')],['flight:02.01','flight:02.01.03','flight:07.04']);

topics.busbar = article('power-bus-conductors',
 'Bus conductors carry substantial electrical current between the power system and its loads. Their cross-section, route, insulation and joints influence voltage drop, heat generation and the physical organization of the core.',[
 section('purpose','A shared route for electrical energy','A power bus supplies several consumers from a common electrical source or distribution point. Conductors must carry the intended current while keeping losses and unwanted voltage differences within the electrical design. A modeled copper bar identifies a material allocation, not a completed conductor sizing calculation. The terminal hardware, insulating supports and return-current path are equally important parts of a usable power connection.','power','busbars'),
 section('operation','Resistance, heating and changing currents','Current through resistance produces both a voltage drop and heat. Increasing conductor cross-section reduces resistance, while length and joint resistance work in the opposite direction. Rapidly changing current also makes the geometry of the outgoing and return paths important because their loop has inductance. Laminated busbars place conductors and insulation in a controlled stack; flexible cables solve some accommodation problems differently. Neither construction can be chosen from appearance alone.','busbars'),
 section('engineering','Connections often govern the installation','A bar needs mechanically supported terminals that maintain contact pressure without damaging its insulation. Differential expansion, vibration, access for assembly and the intended electrical bond to surrounding structure must be considered. Copper is a familiar conductive option; aluminum changes mass, cross-section and joining requirements. The workbench’s dry electrical conductors are separate from fluid-wetted thermal hardware, so their copper allocation must not be carried over to an ammonia passage.','workmanship','iss-atcs')],
 [maker('Rogers Corporation','ROLINX laminated busbars','A real industrial manufacturing comparison for conductor and dielectric stacks; it is not a space-qualified installation selection.','busbars')],
 [alternative('Insulated cable harness','Can accommodate flexible routes and separate branch connections.','Bend space, terminations and thermal behavior differ from a rigid bar.','harness'),alternative('Laminated conductor assembly','Can bring supply and return paths close together in a compact package.','The insulation stack and terminal geometry require coordinated fabrication.','busbars')],
 ['This allocation may have no separate visible geometry. Use its parent power unit to understand the electrical boundary; hidden conductors still contribute to the parent mass allocation.'],
 [term('Voltage drop','The reduction in voltage caused by current passing through impedance.'),term('Inductance','The property that relates changing current to an induced voltage.')],['flight:02.03','flight:02.03.01','flight:07.05']);

function coldPlate(hardware) {
 const kind=hardware?.energySystem?.thermal?.kind;
 const specific=kind==='passive-local'?'In the passive-local architecture, this allocation is a local spreader and contact interface feeding passive heat transport. It does not establish a pumped passage or a liquid connection.':kind==='heat-lift'?'In the heat-lift architecture, this interface delivers payload heat to the cold side of the thermal system. Refrigerant, passage construction and operating pressure remain unresolved; the housing appearance supplies none of those answers.':'In the pumped architecture, payload heat reaches the circulating coolant through the cold-plate wall. The current ammonia material basis excludes copper-bearing wetted parts; the dry electrical busbars elsewhere in the core have a different function.';
 return article('payload-thermal-interface-'+(kind||'pumped'),
  'A cold plate or local spreader collects concentrated heat from computing hardware and distributes it into a larger thermal path. Its effectiveness depends on contact quality as well as the metal from which it is made.',[
  section('purpose','Connecting a hot device to the cooling system','Processor packages occupy relatively small areas but can dissipate considerable power. The local thermal interface spreads that heat so the downstream system can carry it away without an excessive temperature rise at the device. Mounting pressure, flatness and any interface material influence that first step. A large radiator cannot compensate for an ineffective contact immediately above a hot package.','thermal','act-chassis'),
  section('operation','The heat path in this configuration',specific+' In every case, the useful question is where heat enters, which material or fluid carries it onward, and which contact adds thermal resistance. A plate’s external shape alone does not reveal its internal flow channels or thermal performance.','heat-pipes','iss-atcs','redwire'),
  section('engineering','Choosing construction and interfaces','Machined or joined metal plates can integrate mounting and heat-transfer surfaces. Embedded heat pipes offer another way to spread heat, while a fluid cold plate needs compatible passages, joints and connections. Engineers balance mass, stiffness, pressure requirements where applicable and the permissible temperature rise. Surface flatness and assembly procedures deserve the same attention as bulk conductivity, because the actual path includes every joint between the package and the thermal system.','act-hik','act-chassis')],
  [maker('Advanced Cooling Technologies','HiK plates and embedded heat-pipe technology','A useful comparison for spreading concentrated heat. Copper/water examples are not interchangeable with ammonia-wetted hardware.','act-hik'),maker('Redwire','ODC thermal architecture study','A relevant local heat-transport reference; it is not a supplier drawing for this plate.','redwire')],
  [alternative('Solid heat spreader','Distributes heat without an internal working fluid.','Long distances or high heat loads can require more metal or a larger temperature difference.','thermal'),alternative('Embedded heat pipes','Move heat through phase change within a plate or panel.','Operating temperature, wick behavior and working-fluid compatibility must be established.','heat-pipes')],
  ['Follow the contact from the compute assembly toward the thermal transport allocation. Internal channels and contact pressure are not established by surface detail.'],
  [term('Thermal resistance','Temperature rise per unit of heat flow through a path.'),term('Spreader','A part that distributes heat from a concentrated source over a larger area.')],['flight:01.01','flight:01.01.02','flight:03.02','flight:03.01']);
}

function radiatorFinish(record) {
 const paint=record.materialId==='radiator-white-paint';
 return article(paint?'radiator-white-coating':'radiator-glass-osr',
  paint?'The radiator’s white coating controls how its exposed surface exchanges radiation with the environment. It is a functional thermal finish over a structural panel, not merely white paint chosen for appearance.':'Optical solar reflectors are thin glass-and-coating assemblies on the radiator surface. They help the panel emit thermal radiation while limiting absorbed sunlight, combining optical behavior with a demanding bonded installation.',[
  section('purpose','The surface that space sees','Heat delivered to a radiator must leave its exposed surfaces as thermal radiation. At the same time, those surfaces may absorb sunlight and radiation from Earth or nearby hardware. Solar absorptance and infrared emittance describe different parts of this exchange; a surface can be reflective to sunlight yet useful as a thermal emitter. Its visible color alone does not supply the coefficients needed for analysis.','thermal'),
  section('operation',paint?'How a white thermal coating works':'How a second-surface reflector works',paint?'A thermal-control coating uses a specified pigment and binder system to establish its optical behavior. AZ-93 is a real example relevant to the study’s white-finish option. The coating must be applied to a prepared substrate with controlled thickness and curing; damage, contamination and environmental exposure can change the surface. The structural aluminum beneath it spreads heat, while the coating defines the exposed radiative boundary.':'In a second-surface reflector, light passes through a transparent face toward a reflective layer behind it. The optical stack is chosen for the intended spectral behavior, while the glass surface participates in infrared heat exchange. Individual tiles or elements must be bonded and accommodated as the panel changes temperature. Actual products differ in glass and coating construction; OSR does not name one universal material.',paint?'az93':'osr'),
  section('engineering','Finishing a deployable radiator','Adhesion, substrate preparation, edge treatment, contamination control and environmental durability affect both manufacture and lifetime. A tiled finish introduces joints and bonding details; a coating introduces application and repair procedures. Either must remain compatible with the panel’s temperature and deformation. The selected look in the viewer follows the material option, while the thermal model’s controlled optical inputs remain the values used for performance calculations.','act-radiator','redwire')],
  [maker(paint?'AZ Technology':'Excelitas / Qioptiq',paint?'AZ-93 white coating':'Optical Solar Reflector families',paint?'A real thermal coating example, not a released application specification for these panels.':'Real glass reflector products for comparison; no particular glass or conductive layer is selected here.',paint?'az93':'osr')],
  [alternative(paint?'Glass OSR finish':'White thermal-control coating',paint?'Provides another way to combine solar reflectance with thermal emission.':'Can cover complex surfaces without an array of separate glass elements.',paint?'Adds tile bonding, joints and glass-handling considerations.':'Application process, aging and optical performance must match the mission.',paint?'osr':'az93'),alternative('Different controlled optical stack','Can address a different temperature or environmental requirement.','The choice requires measured properties and a compatible substrate, not a color match.','thermal')],
  ['Compare the finish with the panel edge underneath. Neither simulated gloss nor tile pitch is a measured thermal-optical property.'],
  [term('Absorptance','The fraction of incident radiation absorbed by a surface.'),term('Emittance','How effectively a surface emits thermal radiation compared with an ideal emitter.')],['flight:03.01','flight:03.01.02','flight:03.01.03']);
}

topics.radiatorFace = article('radiator-face-sheets',
 'Radiator face sheets are the load-carrying skins beneath the emitting finish. They help keep a large panel stiff and spread heat from internal transport hardware toward the area that can radiate it away.',[
 section('purpose','A panel skin with two jobs','A deployable radiator must survive launch and deployment while providing a useful thermal surface in orbit. Its skins form part of the structural panel, carrying tension or compression when the panel bends. They also connect heat-transfer features to the external finish. Those functions can compete: a thinner skin saves mass, while thicker material may improve local stiffness and heat spreading.','act-radiator'),
 section('operation','How heat reaches the whole surface','Heat entering near a tube or embedded heat pipe spreads through the metal and bonded interfaces before reaching the emitting surface. A very large geometric area is less useful if regions far from the transport path remain much colder than the heated region. The layout of transport elements, sheet conductivity and bond quality therefore work together. The outer coating or OSR establishes radiation behavior; it does not replace the conductive role of the underlying face sheet.','thermal','redwire'),
 section('engineering','Manufacture and load introduction','A sandwich panel usually joins its skins to a lightweight core, with locally reinforced regions where hinges, brackets or tube attachments introduce loads. Engineers consider flatness, bond preparation, thermal expansion and the stresses generated by repeated temperature changes. Aluminum is a relevant study allocation, but the grade, temper, gauge and joining process require selection. A machining texture or metallic edge cannot establish those engineering details.','beyond-structures','act-radiator')],
 [maker('Advanced Cooling Technologies','Honeycomb radiator panels','A real integrated-panel comparison connecting structural construction with thermal transport.','act-radiator'),maker('Redwire','ODC power and thermal study','Identifies aluminum radiator face sheets in its architecture discussion; it does not specify every panel in this workbench.','redwire')],
 [alternative('Different skin thickness or alloy','Can shift the balance among stiffness, heat spreading and mass.','Changes must be assessed with the core, joints and load cases.','structures'),alternative('Composite structural skin with a thermal path','May suit a stiffness or expansion requirement.','Heat spreading and metal-to-composite interfaces need separate attention.','beyond-structures')],
 ['Use an edge or inspection view to distinguish structural skin from the emitting finish. The face sheet is not an additional separately counted radiator.'],
 [term('Face sheet','A structural skin bonded to a sandwich core.'),term('Gauge','The specified thickness of sheet material.')],['flight:03.01.01','flight:03.01.03','flight:03.01.04']);

topics.radiatorCore = article('radiator-sandwich-core',
 'The radiator core separates and supports its thin face sheets, producing a stiff panel without filling the entire volume with metal. Its structural role is different from the radiating finish and from the fluid passages.',[
 section('purpose','Making a broad, lightweight panel','Two skins spaced apart can resist bending efficiently, provided a core holds their separation and transfers load between them. A honeycomb core supplies that support with a cellular structure and relatively little material. This is useful for large panels that must be light but cannot behave like loose foil during launch or deployment. Local attachments still need a deliberate path through the sandwich.','beyond-structures','structures'),
 section('operation','Cells, bonds and local loads','The skins carry much of the bending tension and compression, while the core and its bonds transfer shear and support the skins against local deformation. A hinge or bracket cannot simply rely on a thin exposed skin over empty cells; inserts or reinforcement distribute concentrated loads. In a radiator, the core must also coexist with embedded transport hardware and the desired heat path to the outer skins.','act-radiator'),
 section('engineering','Why honeycomb is only one allocation','Cell size, foil thickness, material, adhesive and bond process affect stiffness, mass and manufacturability. Open edges, enclosed volumes and assembly venting also deserve attention. The Redwire architecture paper discusses more than one core or spreader approach, including foam and honeycomb options; that does not establish a single universal radiator construction. Here the cellular appearance helps explain a sandwich panel without certifying its detailed internal design.','redwire','beyond-structures')],
 [maker('Advanced Cooling Technologies','Honeycomb radiator-panel construction','A relevant manufacturing example with integrated thermal hardware, not a specified supplier for this core.','act-radiator'),maker('Beyond Gravity','Sandwich spacecraft panels','Examples of real panels and inserts to compare load introduction and fabrication.','beyond-structures')],
 [alternative('Foam-based core or spreader','Offers a different internal structure and possible heat-spreading behavior.','Density, conductivity, bonding and local-load capacity must be compared.','redwire'),alternative('Stiffened metal panel','Uses ribs or other features instead of a bonded cellular sandwich.','Mass, thermal distortion and fabrication trade differently.','structures')],
 ['Honeycomb should normally be hidden beneath the face sheets. An exposed edge or cutaway teaches construction; it is not the radiator’s emitting surface.'],
 [term('Shear transfer','Passing a load parallel to a bonded interface.'),term('Insert','A local fitting that introduces an attachment load into a lightweight panel.')],['flight:03.01.02','flight:03.01.04','flight:07.02.03']);

function radiatorPassage(hardware) {
 const lift=hardware?.energySystem?.thermal?.kind==='heat-lift';
 return article(lift?'heat-lift-radiator-passages':'pumped-radiator-passages',
  'Radiator passages carry thermal energy through the panel to locations where it can spread into the emitting surfaces. Their fluid boundary and their bond to the panel are distinct engineering interfaces that must both work.',[
  section('purpose','Delivering heat across a radiator','A remote radiator cannot reject payload heat unless there is a continuous transport path into it. Passages distribute the transported energy along the panel, reducing the distance heat must travel only through the thin face sheets. Their routing must also fit hinges, panel supports and deployment geometry. The external radiator outline does not reveal flow distribution, pressure loss or local temperatures.','iss-atcs','act-radiator'),
  section('operation','The working-fluid boundary',lift?'In the heat-lift configuration, these are hot-side transport passages associated with an analytical heat-pump architecture. Higher rejection temperature can help a radiator reject heat, but it also changes demands on seals, joints, coatings and working fluid. Refrigerant and operating pressure have not been selected here. An aluminum-looking passage must not inherit compatibility claims from the separate ammonia-loop architecture.':'In the pumped configuration, coolant moves through passages and transfers heat through their walls into the radiator structure. Flow distribution and the temperature change along a path influence how uniformly the panel is used. Aluminum passage material is a study allocation associated with the ammonia-loop basis; exact alloy, joint process and fluid cleanliness still require selection. Copper-bearing wetted parts are excluded from that basis.',lift?'heat-pump':'iss-atcs'),
  section('engineering','Joining thermal and pressure hardware','The passage wall must contain the fluid while maintaining a useful thermal contact with the skin or spreader. Brazing, welding, bonding or integrated manufacture each impose different material and inspection requirements. Flexible or articulated connections near moving panels need their own accommodation. Pressure tests and thermal tests answer different questions: a leak-tight passage can still have an ineffective bond to the radiator surface.','act-radiator','thermal')],
  [maker('Advanced Cooling Technologies','Integrated radiator panels','A useful example of panel and transport integration; its heat-pipe products do not identify the working fluid or passage design selected here.','act-radiator')],
  [alternative('Embedded heat pipes','Can distribute heat through sealed passive devices.','Operating range and capillary limits replace some pumped-flow considerations.','heat-pipes'),alternative('Different passage spacing or parallel routing','Can change temperature uniformity and pressure loss.','Additional joints and flow balancing may be needed.','iss-atcs')],
  ['Look for how the thermal allocation enters the panel. Internal channels, wall thickness and fluid distribution are not certified by the visible tube pattern.'],
  [term('Wetted material','Material directly in contact with the working fluid.'),term('Pressure boundary','The structure that contains a pressurized fluid.')],['flight:03.01','flight:03.01.02','flight:03.02']);
}

topics.coolant = article('pumped-coolant-hardware',
 'Headers, lines, fittings and pump shells form the physical network that moves heat between the payload and radiators. They must maintain a clean, compatible fluid circuit while fitting the spacecraft’s structural and deployment layout.',[
 section('purpose','Connecting separated thermal equipment','The payload and its heat-rejection surfaces may be far apart, so a pumped loop transports energy rather than relying entirely on conduction through the structure. Headers collect or divide flow, lines carry it, fittings join components and the pump supplies the pressure difference needed to circulate it. The ISS thermal system is a useful example of these functions, although its scale and architecture are not the workbench’s design.','iss-atcs'),
 section('operation','Flow has a cost','As coolant passes through lines, bends and components, pressure is lost. The pump must overcome that resistance, consuming electrical power that also eventually becomes heat. Flow distribution influences component temperatures, so routing is an analytical problem as well as a packaging task. The modeled stainless headers and aluminum radiator passages have different locations and interfaces; a single silver appearance should not erase those distinctions.','iss-atcs','thermal'),
 section('engineering','Materials and joints follow the fluid','A material choice must be compatible with the actual fluid, temperature, pressure and cleanliness requirements. The current ammonia basis excludes copper-bearing wetted parts. Welded or brazed joints can reduce separable connections; fittings can simplify integration but add interfaces to inspect. Mounts must support lines without making every thermal expansion or vibration load enter a fragile port. Pump internals, sealing details and verified pressure ratings are not established by this surface allocation.','heat-pipes','structures')],
 [maker('NASA / ISS program','Active thermal-control system reference','A documented system example for following heat collection, transport and rejection; not a procurement source for the modeled plumbing.','iss-atcs'),maker('Advanced Cooling Technologies','Spacecraft thermal hardware','A relevant thermal-manufacturing comparison; individual products require a matched fluid and interface specification.','act-radiator')],
 [alternative('Local passive transport','Can connect nearby heat sources and radiators without a circulation pump.','Distance, temperature difference and passive transport limits govern feasibility.','heat-pipes'),alternative('Separate redundant loops','Can create multiple thermal transport paths.','Additional pumps, plumbing and controls consume mass and power.','iss-atcs')],
 ['Trace the loop between payload and radiator allocations. Rendered lines are accommodation paths, not released plumbing isometrics or weld maps.'],
 [term('Header','A manifold that distributes or collects fluid among branches.'),term('Pressure loss','The reduction in fluid pressure along a flow path.')],['flight:03.02','flight:03.01.04','flight:01.01.01']);

topics.passive = article('local-heat-pipes-and-straps',
 'Local heat pipes and thermal straps carry heat from equipment toward a nearby radiator without a continuously powered circulation pump. A heat pipe and a strap perform similar system roles through different physical mechanisms.',[
 section('purpose','A short, deliberate heat path','When a heat source and its radiator can be placed near one another, local transport can avoid the accommodation of a large pumped circuit. A solid or flexible strap provides a conductive link; a heat pipe transports energy inside a sealed device. Choosing between them depends on distance, temperature difference, flexibility and heat load. The passive-local architecture should not be read as a hidden version of the pumped ammonia loop.','redwire','thermal'),
 section('operation','Conduction versus phase change','A strap conducts heat through metal or another thermally conductive material. Its end contacts can be as important as the strap itself. In a heat pipe, liquid evaporates near the warm end, vapor moves toward a cooler region and condenses, and a wick can return liquid to complete the cycle. Working fluid, wick and geometry determine the operating range and transport limits; a metal tube alone does not prove heat-pipe behavior.','heat-pipes'),
 section('engineering','Mechanical flexibility is useful too','A flexible strap can carry heat while allowing relative motion or reducing a rigid structural connection between equipment. Heat pipes may be integrated into plates or panels to spread heat over a wider area. Materials must be selected as compatible systems: copper/water and aluminum/ammonia are different technologies, not interchangeable appearances. The model allocates local transport without selecting a wick, working fluid, startup behavior or a complete joint design.','act-hik','thermal')],
 [maker('Advanced Cooling Technologies','Heat pipes and HiK plates','Real examples of embedded passive transport; copper/water products are a comparison, not the selected working-fluid system.','act-hik'),maker('Redwire','ODC local thermal architecture','A relevant reference for placing transport near the payload and radiator.','redwire')],
 [alternative('Solid or flexible thermal strap','A straightforward conductive connection with no internal working fluid.','Long paths or large loads can demand more material or temperature difference.','thermal'),alternative('Pumped liquid loop','Can distribute heat across a larger separated system.','Adds pump power, fluid-routing and control requirements.','iss-atcs')],
 ['Follow the local path from the payload toward the radiator. The casing shape does not show an actual wick, fluid charge or strap laminate.'],
 [term('Wick','A porous or grooved structure that returns liquid by capillary action.'),term('Capillary limit','A heat-pipe operating limit associated with available liquid-return pressure.')],['flight:03.02','flight:01.01.01','flight:03.01']);

topics.heatPump = article('heat-pump-enclosure',
 'A heat-pump enclosure packages equipment that uses electrical work to raise the temperature at which heat is rejected. It is more than a circulation-pump cover: the underlying thermal cycle changes the spacecraft’s power and radiator requirements.',[
 section('purpose','Moving heat to a hotter rejection system','A conventional thermal path carries heat from hotter equipment toward a colder sink. A heat pump adds work so that heat can be rejected at a higher temperature than the heat-collection side. That can change radiator sizing, but the added electrical input must also be rejected as heat. A useful architecture comparison therefore includes the power system and both sides of the thermal circuit.','heat-pump','thermal'),
 section('operation','The machinery behind the housing','A vapor-compression approach includes an evaporator, compressor, condenser and expansion function, with a working fluid moving among pressure and temperature conditions. Space operation changes how liquid and vapor distribute and how startup is managed. NASA’s Tech Brief is a research reference for those issues. The workbench’s analytical heat-lift package does not establish a selected compressor, refrigerant, lubricant or internal flow arrangement.','heat-pump'),
 section('engineering','Several interfaces share one package','The motor drive needs electrical power and cooling; the compressor introduces mechanical loads; the fluid circuit needs pressure containment and compatible joints. Housing mounts must account for those functions without assuming that an aluminum exterior is the pressure vessel itself. Temperature differences across the package also influence materials and clearances. Developing this part would require coordinated mechanical, electrical and thermodynamic design rather than scaling a familiar pump-shaped object.','structures','workmanship')],
 [maker('NASA Johnson Space Center','Spacecraft vapor-compression heat-pump research','A primary research reference for the architecture and microgravity considerations. It is not a commercial off-the-shelf selection.','heat-pump')],
 [alternative('Direct rejection with a larger radiator','Avoids the heat-lift compressor cycle.','The required radiator depends on payload temperature and environmental heat loads.','thermal'),alternative('Local heat pipes and spreaders','Can support a passive architecture when useful temperature differences exist.','They do not independently lift heat to a hotter sink.','heat-pipes')],
 ['Treat the housing as an accommodation envelope. Compressor internals, refrigerant, pressure rating and vibration isolation have not been resolved by this model.'],
 [term('Heat lift','Using work to transfer heat to a higher rejection temperature.'),term('Condenser','The heat exchanger where vapor rejects heat and condenses in a vapor-compression cycle.')],['flight:03.02','flight:03.02.02','flight:03.01.04','flight:02.03']);

topics.heatLiftLines = article('heat-lift-transport-lines',
 'Heat-lift transport lines connect the cold and hot parts of an analytical heat-pump system. Their required materials and construction depend on a working fluid and operating conditions that have not yet been selected.',[
 section('purpose','Connecting unlike thermal conditions','A heat-pump architecture includes heat collection, compression or another work input, and heat rejection. Connections among those functions may encounter different pressures, temperatures and fluid phases. The transport network must support the thermodynamic architecture while fitting around equipment and any moving panels. Calling every silver line a coolant tube hides these important differences between branches.','heat-pump'),
 section('operation','Fluid state changes the design problem','A single-phase line, a vapor line and a two-phase connection can have very different pressure-loss and fluid-management behavior. In low gravity, liquid does not simply collect at the bottom of a component as it would on the ground. Startup, shutdown and transient operation therefore matter alongside the nominal steady state. The current rendering identifies routes, not a solved refrigerant circuit or a demonstrated microgravity fluid-control system.','heat-pump'),
 section('engineering','Why the material remains unresolved','Stainless appearance is only a preliminary visual allocation. Fluid compatibility, pressure, hot-side temperature, seals, joining and cleanliness must be selected together before a flight line can be specified. Mounting clamps and flexible sections must accommodate movement without imposing uncontrolled loads on component ports. The established material assumptions for the separate pumped-ammonia architecture cannot be transferred to this branch merely because both architectures move heat through tubes.','iss-atcs','structures')],
 [maker('NASA Johnson Space Center','Heat-pump technology research','Provides a real engineering context for the fluid-network problem, not a released design for these lines.','heat-pump'),maker('Advanced Cooling Technologies','Integrated thermal-hardware examples','Useful for studying panel and transport interfaces; the cited radiator products do not establish a heat-lift refrigerant.','act-radiator')],
 [alternative('Separate secondary transport loop','Can place an interface heat exchanger between the heat pump and remote equipment.','Adds thermal resistance, pumping or other transport equipment and more interfaces.','iss-atcs'),alternative('Direct heat-pump circuit connection','Can reduce the number of intermediate heat exchanges.','Extends the working-fluid circuit and its operating constraints through more of the spacecraft.','heat-pump')],
 ['Use the routes to understand accommodation only. Hot and cold branches, phase boundaries and qualified pressure joints are not fully resolved.'],
 [term('Two-phase flow','Flow containing both liquid and vapor.'),term('Secondary loop','A separate transport circuit coupled through a heat exchanger.')],['flight:03.02.01','flight:03.01.04','flight:01.01.01']);

topics.mliAmber = article('amber-blanket-outer-cover',
 'The amber outer blanket is the visible cover of a multilayer insulation assembly. Its gold-like appearance comes from the optical behavior of a polymer film and reflective backing, not from a blanket made of gold metal.',[
 section('purpose','The outer boundary of an insulation system','A spacecraft blanket limits unwanted radiative heat exchange between equipment and its surroundings. The outer cover faces sunlight, Earth radiation and nearby hardware while protecting the more delicate layers beneath it. Its properties therefore need to be considered separately from the effective insulation of the complete stack. A spacecraft can use different outer covers in different locations because exposure and equipment temperature requirements differ.','mli-optics'),
 section('operation','Why the surface looks amber','Polyimide film can have an amber appearance, while an aluminum reflective layer changes how incident light is reflected through the film. The underlying blanket contains separated reflective layers that reduce radiative exchange. Neither the visible color nor the number of wrinkles reveals the complete stack’s performance. Compression, seams and attachments can create local heat paths that are absent from a simple flat-film illustration.','mli-optics','sheldahl'),
 section('engineering','A blanket is fabricated around its equipment','Patterns, seams, cutouts and attachment points need to fit the actual hardware without blocking connectors, vents, moving joints or radiator surfaces. The construction may also need controlled electrical grounding and protection appropriate to the orbital environment. Film gauge, coating, spacers and venting remain separate choices. A visually realistic fold is helpful for recognizing a blanket, but it is not a fabrication pattern or evidence of a qualified layup.','sheldahl','thermal')],
 [maker('Sheldahl','Coated films and blanket materials','A primary material reference for comparing polymer films and reflective layers; the full blanket supplier is not selected here.','sheldahl')],
 [alternative('White outer cover','Can provide a different environmental and optical outer surface over insulation.','The outer cover and concealed stack still require coordinated design.','beta'),alternative('Different coated-film stack','Can be tailored for exposure, grounding or handling requirements.','Changing one layer changes more than appearance and requires property verification.','sheldahl')],
 ['Distinguish the amber cover from the white blanket zones and radiator faces. Wrinkles and seams are illustrative, and concealed layer count is not shown.'],
 [term('MLI','Multilayer insulation: separated reflective layers that reduce radiative heat transfer.'),term('Outer cover','The exposed protective and optical surface of a blanket assembly.')],['flight:03.03','flight:03.03.02','flight:03.03.03']);

topics.mliWhite = article('white-blanket-outer-cover',
 'The white blanket cover is a protective outer layer over insulation. The study uses the Beta-cloth material class: a glass-fabric construction associated with PTFE, rather than white radiator paint or a solid structural panel.',[
 section('purpose','Protecting the insulation underneath','Outer covers make delicate insulation assemblies easier to handle and help them tolerate their local environment. A white cover also presents different optical behavior from an amber polymer face. The selection depends on where the blanket sits, what it sees and how it is attached. Its presence does not by itself establish a debris shield, a pressure barrier or the complete thermal performance of the underlying insulation.','beta','mli-optics'),
 section('operation','Fabric and reflective layers do different jobs','The woven cover provides the external surface while the separated reflective layers beneath it reduce radiative transfer. Seams, hems, penetrations and fasteners connect those layers to real equipment and can alter local heat flow. A visible fabric weave therefore explains only part of the assembly. The cover must remain compatible with the insulation stack and must not bridge moving equipment or obscure surfaces intended to radiate heat.','sheldahl','thermal'),
 section('engineering','Choosing a cover construction','Fabric weight, coatings, edge treatment, stitching or other joining methods affect handling and fabrication. Designers also consider contamination, electrical continuity where required and the local exposure conditions. The workbench’s white cloth appearance identifies a material allocation without setting the exact product, blanket pattern or environmental qualification. It should be compared with the amber cover as a different outer-surface choice, not as proof that one location has more insulation layers.','beta','sheldahl')],
 [maker('Dunmore','Beta cloth materials','A real manufacturer reference for the PTFE/glass-fabric material class; no particular grade or finished blanket is selected.','beta'),maker('Sheldahl','Space thermal-control material handbook','Useful for placing the cover within a larger menu of blanket films and constructions.','sheldahl')],
 [alternative('Aluminized polymer outer film','Provides a lightweight film-based external surface.','Handling, optical behavior and environmental protection differ from fabric.','mli-optics'),alternative('Locally reinforced blanket cover','Can address attachment or handling demands around a specific feature.','Reinforcement adds stiffness and may create local thermal paths.','thermal')],
 ['Look for the boundary between a white fabric-covered blanket and a rigid white radiator. Similar color does not mean the same material or function.'],
 [term('Beta cloth','A glass-fabric material class associated with a PTFE treatment.'),term('Thermal bridge','A local path that transfers more heat across an insulating assembly.')],['flight:03.03.01','flight:03.03.03','flight:03.01.01']);

topics.mliInner = article('concealed-reflective-insulation-stack',
 'The concealed reflective stack supplies much of a multilayer blanket’s insulating function. Several thin layers and spacers work together to reduce radiative heat exchange while limiting direct conductive contact between layers.',[
 section('purpose','Insulation without a thick solid wall','In vacuum there is no surrounding air to provide ordinary convective heat transfer, but surfaces still exchange radiation. A stack of reflective layers interrupts that exchange through multiple surfaces. The layer count alone is not a useful performance specification: materials, spacing, seams, compression and installation all influence the effective result. The outer cover and the hidden stack must therefore be described separately.','mli-optics','thermal'),
 section('operation','Keeping the layers from becoming one conductor','Reflective films need separation so that unwanted contact does not dominate heat transfer. Spacers or other construction details maintain that separation while allowing the blanket to be assembled and vented. A tightly crushed stack can behave differently from its intended installation. Edges and penetrations also matter because they interrupt the ideal large-area arrangement and create local paths between the equipment and environment.','sheldahl','mli-optics'),
 section('engineering','Making a blanket that fits','A usable insulation assembly needs patterns, overlaps, attachments and access around real connectors and supports. Layer materials must be compatible with the temperature and exposure expected inside the blanket, while fabrication must control contamination and damage. An engineering thermal model often represents the installed blanket with effective properties; it should not silently substitute the optical properties of one film. This concealed allocation is educational even when no individual layers are drawn.','thermal','sheldahl')],
 [maker('Sheldahl','Reflective films and thermal-control materials','A real handbook for comparing potential layer materials; it does not define this blanket’s complete recipe.','sheldahl'),maker('NASA','MLI optical-property research','A primary source for understanding why outer-film measurements and assembled-blanket behavior are different questions.','mli-optics')],
 [alternative('Different layer and spacer construction','Can be adapted to temperature, handling and mass requirements.','More layers are not automatically better if installation creates excessive contact.','sheldahl'),alternative('Controlled conductive mounting','Can deliberately couple equipment to a thermal sink where insulation is undesirable.','The resulting heat path must be designed with the surrounding blanket.','thermal')],
 ['No separate geometry may be available for this stack. Its mass and function remain within the parent blanket assembly rather than adding another external shell.'],
 [term('Effective emittance','A system-level parameter representing the radiative behavior of an assembly.'),term('Spacer','Material or geometry that keeps adjacent reflective layers apart.')],['flight:03.03','flight:03.03.01','flight:03.03.02']);

topics.cmg = article('cmg-housing-and-gimbal-frame',
 'A CMG housing and gimbal frame support a spinning momentum assembly and transmit its controlled reaction torque into the spacecraft. They are precision structural parts in an actuator, not simply protective covers around a wheel.',[
 section('purpose','Turning stored momentum into attitude control','A control moment gyroscope changes the direction of a spinning rotor’s angular momentum to produce torque on the spacecraft. Its frame must react the resulting loads and locate the gimbal axis consistently. Several units can work together to provide useful control authority. The mounting structure is therefore part of the attitude-control path, connecting moving internal hardware to the core rather than isolating it as loose machinery.','cmg','gnc'),
 section('operation','The interfaces around a moving rotor','A working unit includes rotor support, a gimbal, drive and sensing functions, and electrical connections. Bearings and alignment control the motion; the base transmits loads and provides a thermal path for losses in motors and electronics. Cable or rotating-connection accommodation must remain compatible with the intended motion. The exterior model illustrates that arrangement without establishing the actual bearing design, balance quality or internal clearances.','cmg'),
 section('engineering','Stiffness, alignment and disturbance','Mounting flexibility can couple actuator motion into structural vibration, while misalignment changes the relationship between commanded and delivered torque. Designers assess the unit together with the supporting panel or frame, its thermal environment and the spacecraft control law. A machined or cast housing must preserve interfaces after launch loads and temperature changes. Surface anodizing is a finishing choice; it is not evidence of the actuator’s accuracy, momentum capacity or qualification.','structures','anodize')],
 [maker('Airbus','CMG 15-45 S','A real gimballed momentum-actuator reference with defined interfaces. It does not establish a literal internal design for these scaled housings.','cmg')],
 [alternative('Reaction-wheel assembly','Changes wheel speed to exchange momentum with the spacecraft.','Torque capability and control architecture differ from gimballed momentum exchange.','gnc'),alternative('Different CMG mounting arrangement','Can alter packaging and the directions available to the actuator cluster.','Structural dynamics and control singularities need joint analysis.','gnc')],
 ['Identify the gimbal frame, supported housing and attachment to the core. Decorative bearing or fastener detail does not establish a balance or alignment specification.'],
 [term('Gimbal','A pivoting support that changes an assembly’s orientation.'),term('Angular momentum','The rotational quantity whose change is associated with applied torque.')],['flight:04.01','flight:04.02','flight:07.01']);

topics.magCase = article('magnetorquer-outer-casing',
 'The magnetic-rod casing supports and protects an electromagnetic attitude actuator. It provides mounting and accommodation around a winding and magnetic core, while the actuator interacts with the local planetary magnetic field.',[
 section('purpose','Packaging a magnetic actuator','A magnetorquer can apply torque by creating a magnetic dipole that interacts with the external field. It is useful for tasks such as momentum unloading when the orbit and field permit. The casing locates the rod on the spacecraft and protects its winding and connections. It does not generate the magnetic moment by itself, and its black appearance does not identify the magnetic core material.','magnetorquer','gnc'),
 section('operation','Orientation matters as much as appearance','The produced torque depends on the direction of the magnetic dipole relative to the ambient field. At any instant the actuator cannot create an arbitrary torque in every direction. Multiple rod orientations and the changing orbital field help the control system accomplish its task over time. The housing and its mounting should preserve the intended alignment and avoid assuming that a long rod automatically has sufficient authority for a given spacecraft.','gnc'),
 section('engineering','A casing in a magnetic environment','Mechanical supports must retain the assembly through launch while accommodating heat from the winding. Nearby magnetic materials, wiring and sensitive sensors can affect the installation, so placement is an electromagnetic as well as structural choice. A commercial rod datasheet can guide the relevant interfaces, but the actual core, winding, casing alloy and mounting method require selection. The casing material allocation must not be mistaken for the material of every hidden component.','magnetorquer','structures')],
 [maker('NewSpace Systems','Magnetorquer rod families','Real actuator examples for comparing packaging and magnetic-moment requirements; no exact rod product is selected by the visible casing.','magnetorquer')],
 [alternative('Air-core magnetic coil','Produces a magnetic dipole without a ferromagnetic rod core.','Packaging, electrical power and achievable moment differ.','gnc'),alternative('Separate actuator mounts','Can orient individual rods independently around available structure.','More attachments and longer harness routes may be required.','structures')],
 ['Compare rod orientation with its mounting points. The outside finish does not reveal winding turns, magnetic-core alloy or residual magnetism.'],
 [term('Magnetic dipole','A directional magnetic moment produced by a magnet or current loop.'),term('Momentum unloading','Reducing stored momentum in attitude-control devices through an external torque.')],['flight:04.02','flight:04.02.02','flight:04.01']);

topics.magWinding = article('magnetorquer-conductor-winding',
 'The winding is the electrical part of a magnetic actuator: current through its turns creates the magnetic field. It must fit the core and casing while maintaining insulation, electrical continuity and a route for resistive heat.',[
 section('purpose','Converting electrical current into magnetic moment','A current loop produces a magnetic dipole. Repeating turns and, in a rod actuator, combining them with a magnetic core provides a compact way to create the required moment. The winding is therefore an active electromechanical component rather than decorative copper. Its useful output must be considered with the core, drive electronics and external field; copper color alone cannot specify actuator performance.','gnc','magnetorquer'),
 section('operation','More turns involve several tradeoffs','Turn count, current, wire dimensions and winding geometry interact. The conductor has resistance, so energizing the actuator produces heat; insulation must keep adjacent turns from becoming unintended electrical connections. The driver must supply controlled current and manage switching behavior. A real magnetorquer specification relates these electrical inputs to magnetic output and operating conditions instead of treating wire volume as a sufficient design description.','magnetorquer'),
 section('engineering','Building and supporting a coil','Winding processes need controlled wire handling, turn placement, lead termination and appropriate impregnation or retention where selected. The coil must survive vibration and thermal expansion without damaging insulation or loading its terminals. A clear path for heat into its support can be important even when average power is modest. Material and workmanship choices remain component-specific; the rendered copper is not a released wire gauge, insulation system or turn schedule.','workmanship','structures')],
 [maker('NewSpace Systems','Magnetorquer rod products','A real reference for the completed actuator’s magnetic and electrical interface; hidden winding details are not inferred from the model.','magnetorquer'),maker('NASA','Electrical workmanship resources','Useful for understanding why termination and insulation quality matter alongside the electromagnetic design.','workmanship')],
 [alternative('Different wire gauge and turn count','Can trade electrical resistance, current and packaging.','The core and driver must be analyzed with the revised winding.','magnetorquer'),alternative('Air-core coil','Removes the ferromagnetic core from the actuator.','It changes the attainable moment, volume and power requirements.','gnc')],
 ['The winding may be concealed or only suggested in an inspection view. Its detailed turn count and conductor dimensions are not established.'],
 [term('Ampere-turns','Current multiplied by the number of coil turns.'),term('Winding resistance','The electrical resistance of the coil conductor and its connections.')],['flight:04.02','flight:04.02.01','flight:02.03']);

topics.starBaffle = article('star-tracker-baffle',
 'A star-tracker baffle limits unwanted light entering an attitude sensor. It helps the optical head see the star pattern it needs without being overwhelmed by bright objects or reflections outside its intended viewing direction.',[
 section('purpose','Helping a sensor recognize the sky','A star tracker estimates orientation by observing stars and matching their pattern to a reference catalog. Light from the Sun, Earth or nearby illuminated spacecraft surfaces can interfere with that measurement. The baffle is part of the optical head’s defense against stray illumination, defining which rays can reach sensitive surfaces. It must work with the lens, detector, processing and spacecraft placement rather than being treated as a decorative black tube.','hydra','hubble'),
 section('operation','Geometry before black paint','Baffle length, opening and internal geometry can block direct or multiply reflected light paths while preserving the required field of view. Low-reflectance surfaces reduce the light scattered from the remaining illuminated surfaces. A finish that looks black to a human observer may behave differently at the instrument’s wavelengths and angles. The actual exclusion angles and tracking performance belong to the complete optical-head design.','superblack','hydra'),
 section('engineering','Placement, cleanliness and thermal alignment','The sensor needs an unobstructed view in its operating attitudes, so nearby antennas, arrays and blankets affect placement. Its mount must preserve alignment with the spacecraft reference frame through launch and temperature changes. Baffle coatings must also be compatible with the optical cleanliness requirements. The workbench allocates a baffle material class without selecting its vane geometry, measured reflectance or a particular star-tracker product.','structures','superblack')],
 [maker('Sodern','HYDRA star-tracker family','An actual optical-head and electronics architecture for comparison. The model is not a literal HYDRA head or an assertion of its performance.','hydra')],
 [alternative('Different baffle geometry','Can change the balance between clear field of view and stray-light rejection.','Length and opening affect accommodation and thermal behavior.','hubble'),alternative('Different low-reflectance coating','Can improve performance in a particular spectral or angular range.','Qualification, contamination and handling requirements must match the optical system.','superblack')],
 ['This allocation may have no resolved optical-head geometry. Use the attitude-sensor parent and nearby parts to examine potential viewing obstructions.'],
 [term('Stray light','Unwanted illumination reaching an optical system.'),term('Field of view','The angular region an optical instrument is intended to observe.')],['flight:04.03','flight:05.03.02','flight:07.01']);

topics.patchFace = article('s-band-patch-dielectric-face',
 'The pale face of a patch antenna represents a dielectric surface associated with the antenna assembly. A dielectric is electrically insulating, but its electromagnetic properties still influence how radio waves enter and leave the antenna.',[
 section('purpose','An RF surface, not just a protective lid','A patch antenna uses conductive geometry and a dielectric structure to radiate or receive electromagnetic energy. Some products also include a protective radome over the radiating elements. The internal substrate and the outside radome need not be the same material. The workbench does not identify a specific construction, so the visible pale surface should be understood as an allocation around the S-band antenna function.','anywaves','rf-laminate'),
 section('operation','Materials affect the electromagnetic design','Permittivity and loss influence fields within a dielectric, while thickness, shape and interfaces affect antenna behavior. A protective cover must therefore be included in the RF design rather than added as an arbitrary cosmetic shell. The feed, ground structure, mounting surface and nearby spacecraft equipment also interact with the antenna. Mechanical fit alone cannot establish impedance match, pattern or polarization performance.','rf-laminate','anywaves'),
 section('engineering','Comparing real constructions','The Anywaves portfolio shows that even related patch-antenna products can use different radome materials. That is why this model leaves dielectric chemistry unresolved rather than assigning one polymer to every pale antenna face. Selection would also consider temperature, outgassing, environmental exposure and attachment to the metal structure. Manufacturing tolerances and the actual dielectric properties must be assessed together with the electrical design.','anywaves','structures')],
 [maker('Anywaves','S-band patch antenna families','Real antenna examples that help distinguish radome, feed and mounting interfaces; none is identified as the exact modeled antenna.','anywaves'),maker('Rogers Corporation','RT/duroid microwave laminates','A relevant substrate-material comparison, not evidence that the outer cover uses that laminate.','rf-laminate')],
 [alternative('Different dielectric or radome construction','Can meet a different mechanical or electromagnetic requirement.','The antenna must be analyzed and tested with the revised material.','anywaves'),alternative('Another antenna geometry','A non-patch solution can offer different coverage or packaging.','Gain, polarization, accommodation and feed requirements change.','nisar')],
 ['Distinguish the dielectric face from metal support and small feed features. The face color does not identify Vespel, PEEK, ceramic or a selected laminate.'],
 [term('Dielectric','An electrically insulating material that responds to an electric field.'),term('Radome','A cover designed to protect an antenna while allowing its radio-frequency operation.')],['flight:05.01','flight:05.01.02','flight:07.05']);

function rfContact(ka) {
 return article(ka?'ka-feed-contact-finish':'s-band-feed-contact-finish',
  `The ${ka?'Ka-band':'S-band'} contact finish is a thin functional layer on a conductor or connector interface. The gold-colored detail represents plating, not a solid-gold antenna part or a complete RF feed specification.`,[
  section('purpose','Keeping an electrical interface usable','A feed must deliver the intended signal between electronics and an antenna with controlled losses and repeatable connections. Contact plating helps establish a suitable mating surface over a base conductor. The underlying material, plating stack, geometry and contact force work together; a warm metallic color supplies none of those specifications. The structural reflector or antenna support has a different purpose from these small electrical contact regions.','contacts',ka?'nisar':'anywaves'),
  section('operation',ka?'Why the Ka-band feed needs its own design':'Why the S-band feed needs its own design',ka?'At Ka-band, the feed geometry and transmission path are part of a high-frequency system whose surface finish, alignment and discontinuities require careful assessment. Some interfaces carry fields in waveguide rather than through a familiar pin-and-socket contact. The model’s gold accent does not identify which feed construction is used. A low-frequency contact-plating example can teach material layering without qualifying a Ka-band RF connection.':'The feed connects the patch assembly to its radio-frequency signal path. Its construction must preserve the intended impedance and mechanical retention while fitting behind or beside the radiating surface. A connector’s contact coating is only one element: cable transition, ground path and antenna interface also matter. The model does not identify a particular coaxial connector or establish the electrical performance of a plated contact.',ka?'nisar':'anywaves','contacts'),
  section('engineering','Specifying the layer rather than the color','A real contact drawing defines base alloy, intermediate layers, finish thickness and mating requirements. Assembly must preserve cleanliness and avoid damage that changes the contact surface. Glenair’s Micro-D specification is useful because it explicitly distinguishes copper-alloy contacts from gold and nickel finishing layers. It is a materials example here, not evidence that a Micro-D signal connector is the selected RF feed.','contacts','workmanship')],
  [maker('Glenair','Documented contact-plating construction','A primary example of contact materials and finish layers, with a different connector function from an RF feed.','contacts'),maker(ka?'NASA JPL':'Anywaves',ka?'NISAR Ka-band downlink reference':'Patch antenna product portfolio',ka?'A mission-system reference for the surrounding RF architecture, not the supplier of this contact.':'A relevant antenna-level reference for understanding what the contact must connect to.',ka?'nisar':'anywaves')],
  [alternative('Another qualified contact finish','Can meet different mating, corrosion or electrical requirements.','The full connector specification must support the change.','contacts'),alternative('Different feed interface','A different connector or guided-wave arrangement can suit the antenna architecture.','Mechanical and RF interfaces need redesign together.',ka?'nisar':'anywaves')],
  ['The contact finish may be concealed or only visible in close detail. Do not interpret a gold accent as plating on the whole antenna structure.'],
  [term('Plating','A thin deposited layer on a base material.'),term('Impedance match','Compatibility between electrical interfaces that limits unwanted signal reflections.')],ka?['flight:05.02','flight:05.02.01']:['flight:05.01','flight:05.01.01']);
}

topics.reflector = article('ka-reflector-and-support',
 'A reflector redirects radio-frequency energy between a feed and a concentrated beam. Its support structure preserves the shape and alignment needed for that electrical function while carrying launch and operational loads.',[
 section('purpose','Concentrating a communications beam','A reflector antenna can provide a narrower beam than a small low-gain antenna, improving the ability to deliver data to an intended receiver. The feed and reflector geometry form one electromagnetic system. A large dish outline alone does not determine gain or coverage: wavelength, surface accuracy, illumination and pointing all matter. The NISAR downlink paper is a useful real mission reference for the surrounding Ka-band architecture.','nisar'),
 section('operation','Shape and alignment become RF properties','The reflector redirects fields according to its designed surface. Surface error and misplacement of the feed can reduce the intended concentration of energy. Thermal deformation and flexible supports therefore influence communications performance, not just mechanical appearance. The mounting structure must also fit the spacecraft’s pointing strategy and avoid blocking the useful aperture with unrelated equipment.','nisar','structures'),
 section('engineering','Metal and composite implementations','A metallic reflector can combine structural and conductive roles. A composite implementation may use a conductive surface layer while tailoring stiffness or thermal expansion through its laminate. Both need compatible supports, joints and surface manufacturing processes. The workbench allocates aluminum appearance without identifying a supplier reflector or a verified surface tolerance. A high-detail model helps inspect accommodation but does not substitute for antenna measurements.','beyond-structures','act-radiator')],
 [maker('Advanced Cooling Technologies','Panel and reflector-support manufacturing examples','A structural-manufacturing reference, not an RF antenna supplier selection for this dish.','act-radiator'),maker('NASA JPL','NISAR Ka-band downlink system','A real mission reference for studying an antenna in its complete communications system.','nisar')],
 [alternative('Composite reflector with conductive surface','Can tailor structural and thermal behavior.','Coating, laminate and joint tolerances must preserve the RF surface.','beyond-structures'),alternative('Phased-array antenna architecture','Can use an electronically controlled aperture instead of this reflector arrangement.','Power, thermal, control and hardware complexity change substantially.','anywaves')],
 ['Examine the relationship among reflector, feed location and support. The mesh does not establish a measured antenna pattern or surface tolerance.'],
 [term('Aperture','The effective opening or area of an antenna that interacts with the wave.'),term('Feed','The component that couples radio-frequency energy into or out of the antenna.')],['flight:05.02','flight:05.02.02','flight:07.01']);

topics.opticalSupport = article('optical-terminal-yoke',
 'The optical terminal’s support and yoke locate the communications head and, where the architecture permits, allow it to point. They connect a demanding line-of-sight function to a spacecraft that moves and changes temperature.',[
 section('purpose','Holding a precise communications direction','A laser communications terminal exchanges a narrow optical beam with another terminal or ground station. Its support must keep the optical head attached and aligned while accommodating whatever pointing motion the terminal architecture requires. A yoke can support motion around an axis, but not every laser link uses the same pointing scheme. Spacecraft-body pointing and terminal-level steering are different system choices.','optical-terminal','tbird'),
 section('operation','Motion, alignment and connections','A moving head needs bearings or pivots, a drive and position information where those functions are selected. Electrical connections must tolerate the intended travel, and heat needs a path from the head into the supporting system. Flexibility or backlash can affect line-of-sight behavior. The visible yoke therefore represents an important interface even though the model does not resolve the actual bearing, encoder or fine-steering implementation.','optical-terminal','sada'),
 section('engineering','Mounting an optical system on a warm structure','The support must preserve useful alignment after launch loads and across temperature changes. Material expansion, joint stiffness and mounting datums influence that behavior. Machined metal can provide precise interfaces; other structures may be appropriate where mass or thermal stability governs. Surface finish and decorative fasteners do not specify pointing accuracy. The support should be evaluated together with the spacecraft attitude system, optical head and cable routing.','structures','anodize')],
 [maker('Rocket Lab','Optical communications terminal family','A real terminal comparison for packaging and pointing interfaces; this model is not a product-level replica.','optical-terminal'),maker('MIT Lincoln Laboratory','TBIRD demonstration','An alternative mission example for studying how terminal and spacecraft pointing can be coordinated.','tbird')],
 [alternative('Spacecraft-body pointing','Can reduce the need for a large articulating terminal mount.','Communications orientation competes with other spacecraft pointing needs.','tbird'),alternative('Articulated optical head','Provides terminal-level pointing freedom.','Moving joints, cable management and alignment add design work.','optical-terminal')],
 ['Inspect the yoke’s attachment and available motion relative to nearby hardware. Motion range and bearing detail are illustrative unless established in the design facts.'],
 [term('Line of sight','The direction along which the optical terminal transmits or receives.'),term('Backlash','Lost motion when a mechanism reverses direction.')],['flight:05.03','flight:05.03.02','flight:05.03.04','flight:04.01']);

topics.opticalBaffle = article('communications-optical-baffle',
 'The optical communications baffle limits unwanted illumination at the terminal entrance. It protects the useful optical path from stray light while leaving the beam and required pointing region unobstructed.',[
 section('purpose','A clean optical view for a narrow beam','The receiver must distinguish useful light from background and stray illumination. Bright spacecraft surfaces or the Sun can create unwanted paths into the instrument even when they are outside the intended beam direction. A baffle controls some of those paths through geometry and surface behavior. It is related to a star-tracker baffle in principle, but its wavelengths, field requirements and optical functions need their own design.','optical-terminal','superblack'),
 section('operation','Blocking and absorbing unwanted rays','A properly designed entrance structure prevents selected off-axis rays from reaching the sensitive optical train. Its internal surfaces and any vanes reduce secondary reflections. The important property is measured reflectance over the relevant wavelengths and angles, not simply a black visible color. A coating cannot correct every geometric stray-light path, and an overly restrictive opening can obstruct useful pointing or clip the beam.','hubble','superblack'),
 section('engineering','Interfaces with the terminal','The baffle must maintain alignment with the aperture through mounting loads and temperature changes. Contamination or damaged coatings can affect optical performance, so materials and handling provisions matter. Clearance to the yoke and nearby spacecraft structures must hold throughout the allowed motion. The modeled dark anodized surface is an allocation rather than a verified low-reflectance coating or a complete stray-light analysis.','structures','anodize')],
 [maker('Rocket Lab','Optical terminal product family','A real communications-head reference to compare packaging; no internal baffle geometry is selected here.','optical-terminal'),maker('European Space Agency','Superblack coating research','A technical reference for the surface side of stray-light control, not a selected coating vendor.','superblack')],
 [alternative('Longer or differently vaned baffle','Can reject additional unwanted optical paths.','Adds accommodation and can restrict field of regard.','hubble'),alternative('Different absorbing coating','Can target the terminal’s spectral band more effectively.','Environmental durability and optical cleanliness must remain compatible.','superblack')],
 ['Look through the entrance relative to the optical aperture and yoke. Visible rings or surface darkness do not establish a tested stray-light rejection ratio.'],
 [term('Field of regard','The range of directions to which a terminal can point.'),term('Beam clipping','Obstructing part of the intended optical beam.')],['flight:05.03.01','flight:05.03.04','flight:04.03.01']);

topics.opticalFinish = article('optical-head-housing-finish',
 'The white optical-head finish is a thermal surface treatment on the terminal housing. Its role is to help control absorbed environmental energy and radiative heat exchange around an alignment-sensitive optical assembly.',[
 section('purpose','Keeping an optical package thermally predictable','Optical terminals contain structures whose dimensions and alignment can change with temperature. Their housings also receive sunlight and radiation from the environment. A selected external finish helps establish the thermal boundary for the package, while internal conduction and mounting determine how heat is distributed. The white exterior is therefore related to the thermal design even though it is not an active optical element.','thermal','optical-terminal'),
 section('operation','Solar reflection and infrared emission differ','A thermal coating can reflect much of the incident solar energy while emitting infrared radiation effectively. These behaviors occur over different wavelength ranges and cannot be inferred from a rendered white RGB color. AZ-93 provides a real example of the coating class used for the study appearance. Its use as a reference does not establish the exact application thickness or measured properties of this optical head.','az93'),
 section('engineering','Coating around precision interfaces','The housing needs appropriate substrate preparation and a process compatible with nearby optics, seals and mechanical contacts. Optical apertures, electrical bonding lands and thermal joints may require different treatments or masking. Coating durability, contamination and temperature cycling must be considered alongside the terminal’s thermal model. A finish can reduce an environmental heat load, but it does not by itself guarantee optical alignment or remove internally generated heat.','anodize','thermal')],
 [maker('AZ Technology','AZ-93 thermal-control coating','A relevant material-class example; the modeled head has no released supplier application process.','az93'),maker('Rocket Lab','Optical communications terminal reference','Useful for studying the surrounding instrument package, not for attributing this finish to that product.','optical-terminal')],
 [alternative('Different thermal coating or surface stack','Can target a different exposure or temperature requirement.','Measured optical properties and compatibility need reassessment.','osr'),alternative('Local insulation around the head','Can reduce some unwanted heat exchange.','It changes the heat path and must preserve apertures and moving interfaces.','mli-optics')],
 ['Distinguish white housing finish from the transparent aperture and dark baffle. The coating appearance does not identify a vendor terminal.'],
 [term('Solar absorptance','The fraction of incident solar energy absorbed.'),term('Masking','Protecting selected areas from a coating or finishing process.')],['flight:05.03.01','flight:05.03.02','flight:05.03.04','flight:03.01.01']);

topics.opticalAperture = article('optical-terminal-entrance-optic',
 'The entrance optic is the transparent boundary through which the terminal exchanges light. Its shape, glass and coatings must be designed for the actual optical system; a dark blue reflection does not identify those choices.',[
 section('purpose','Admitting the useful beam','An entrance element can be part of a lens system, a protective window or another selected optical arrangement. It must pass the useful wavelengths without introducing unacceptable absorption, reflection or distortion. The surrounding baffle rejects unwanted light, while the aperture must preserve the intended beam. The workbench leaves the optical prescription unresolved rather than pretending that every laser terminal uses the same window.','optical-terminal','hubble'),
 section('operation','Several specifications describe one clear part','Clear aperture describes the usable optical area, not necessarily the full outside diameter. Surface quality, flatness or curvature, thickness and alignment influence what happens to the transmitted wave. Antireflection coatings are specified for wavelength and angle ranges. A catalog window can teach how to read those properties, but its band must match the application; the linked Edmund NIR-I example is not a selection for an unspecified communications wavelength.','window'),
 section('engineering','Glass, coating and mount work together','The mount must retain the optic without imposing excessive distortion as materials expand differently with temperature. Optical cleanliness, handling and environmental protection affect performance throughout integration and operation. For transmitting systems, power density and coating behavior also need assessment for the actual beam. Neither the mesh geometry nor its visual highlight establishes a glass composition, laser-damage threshold or flight-qualified optical assembly.','structures','superblack')],
 [maker('Edmund Optics','Coated fused-silica window example','A laboratory component datasheet for learning optical specifications. Its coating band and environment do not make it the modeled flight optic.','window'),maker('Rocket Lab','Optical communications terminal family','A complete-terminal comparison; its internal prescription is not inferred here.','optical-terminal')],
 [alternative('Separate protective window','Can protect internal optics behind a defined external boundary.','Adds surfaces, possible reflections and a mounting interface.','window'),alternative('Different glass and coating system','Can address a selected wavelength and temperature environment.','Optical transmission, expansion and manufacturing tolerances must be compared together.','window')],
 ['Inspect the entrance optic separately from its baffle and white housing. The model does not resolve a lens prescription or specify a wavelength passband.'],
 [term('Clear aperture','The usable portion of an optic through which the intended light passes.'),term('Optical prescription','The detailed geometry and materials that define an optical system.')],['flight:05.03','flight:05.03.02','flight:05.03.03']);

topics.nozzle = article('engine-expansion-bell-surface',
 'The expansion bell shapes the hot exhaust leaving a rocket engine, turning part of its thermal energy into directed velocity. Its material and cooling approach must suit an extreme local environment, which cannot be inferred from a generic metallic rendering.',[
 section('purpose','The geometry after the throat','A rocket’s chamber and nozzle form a coupled flow system. After the narrow throat, an expanding nozzle accelerates the exhaust and directs it predominantly along the thrust axis. Exit size and shape affect the expansion achieved under the intended operating conditions. A larger bell is therefore a functional geometry, not merely an aesthetic extension; its benefit must be weighed against mass, length and accommodation.','s400'),
 section('operation','Temperature and structure share one thin surface','The nozzle is exposed to hot gas, pressure forces and changing thermal conditions during operation. Different engines manage those conditions through different materials, cooling arrangements and construction. The bell must retain its shape sufficiently for its role while connecting to the chamber or other engine structure. This surface allocation does not provide a heat-flux solution, wall-thickness design or a demonstrated cooling architecture.','s400','structures'),
 section('engineering','What the S400 reference actually establishes','The cited S400 information identifies a platinum-alloy chamber and throat, but that statement does not identify every material throughout the complete expansion bell. The workbench therefore leaves the bell alloy unresolved. Selecting a real construction would require engine-level evidence for materials, joining, thermal behavior and operating life. A neutral metallic surface is more accurate than inventing a refractory alloy, coating or heat-damage pattern from appearance alone.','s400')],
 [maker('ArianeGroup','S400 apogee-motor family','A real storable-engine reference that illustrates chamber/nozzle distinctions. It is not a released drawing or material specification for this scaled bell.','s400')],
 [alternative('Different nozzle expansion geometry','Can change vacuum performance and the physical envelope.','Mass, length and engine-level thermal design change together.','s400'),alternative('Different engine architecture','May suit another thrust or propulsion requirement.','Propellant, feed system and spacecraft integration must be reconsidered as a system.','valves')],
 ['Compare the bell with the engine mounting and nearby structure. The surface does not establish alloy, cooling channels, chamber material or verified wall thickness.'],
 [term('Throat','The narrow nozzle section controlling the flow through a choked rocket nozzle.'),term('Expansion ratio','The ratio of nozzle exit area to throat area.')],['flight:06.01','flight:06.02','flight:06.03','flight:06.04']);

topics.propFeed = article('propellant-feed-and-regulation-hardware',
 'Feed tubes, valves and regulators connect stored fluids to the engine while maintaining their intended separation and operating conditions. The network contains several distinct functions even when its parts share a similar metallic appearance.',[
 section('purpose','Moving fluids under control','Fuel and oxidizer follow separate paths toward a bipropellant engine, while pressurant gas supports the tank pressure architecture. Isolation valves establish boundaries between portions of the system; engine valves control delivery at the thruster; a regulator changes how upstream pressure is supplied downstream. These are different devices with different interfaces. The model’s routed lines illustrate accommodation rather than a complete propulsion plumbing schematic.','valves','pmd'),
 section('operation','Pressure, flow and compatibility','Flow depends on pressure differences and resistance through lines, valves and other components. The required operating conditions at the engine must be considered with tank behavior and the pressurant supply. Every wetted surface encounters its particular fluid, so a material suitable for one branch is not automatically suitable for another. The current stainless appearance is a material-class allocation, not a verified alloy, seal or joining specification.','valves','pressurant'),
 section('engineering','A propulsion network is assembled through interfaces','Line supports must accommodate launch loads and thermal movement without placing uncontrolled loads on ports. Joining and service connections affect cleanliness, leak testing and integration sequence. Electrical valve interfaces need coordinated command and power provisions. A real component datasheet is valuable only when its fluid, temperature, pressure and functional role match the intended installation; an electric-propulsion flow-control product cannot be substituted solely because it is called a regulator.','valves','workmanship')],
 [maker('Moog','Chemical-propulsion valves and helium regulators','A real component portfolio for separating valve and pressure-control functions. Individual products are examples, not selected hardware.','valves'),maker('Northrop Grumman','Propellant and pressurant vessel families','Useful references for the upstream interfaces that the feed network must connect.','pmd','pressurant')],
 [alternative('Regulated pressurization','Can maintain a controlled downstream supply as storage conditions change.','Adds regulation hardware and associated interfaces.','valves'),alternative('Different isolation arrangement','Can divide the system into different controllable sections.','Command logic, leakage boundaries and component count change.','valves')],
 ['Follow fuel, oxidizer and pressurant allocations separately. Rendered fittings do not specify valve seat design, seal chemistry or a released line-routing drawing.'],
 [term('Regulator','A component that controls downstream pressure according to its design.'),term('Isolation valve','A valve used to establish or remove a fluid connection.')],['flight:06.02','flight:06.01','flight:06.03','flight:06.04','flight:06.05']);

function propellantTank(oxidizer) {
 return article(oxidizer?'oxidizer-tank-shell':'fuel-tank-shell',
  `The ${oxidizer?'oxidizer':'fuel'} tank shell contains one of the two separately stored propellants used by the modeled bipropellant system. Its pressure boundary, attachments and internal fluid-management provisions must work together throughout the mission.`,[
  section('purpose',oxidizer?'Keeping the oxidizer separate and available':'Holding fuel for controlled delivery',oxidizer?'The oxidizer supplies the chemical partner needed by the engine rather than relying on oxygen from the surrounding environment. It must remain separate from fuel until the intended engine mixing process. The tank provides storage and a controlled outlet boundary, while upstream pressurization and downstream valves determine how it is used. The oxidizer inventory and vessel structure are different accounting items; a tank shape does not establish the chemical compatibility of its interior.':'The fuel vessel stores the reducing propellant for later delivery to the engine. In orbit the liquid cannot be assumed to remain over an outlet simply because the tank is drawn upright. A propellant-management arrangement helps make liquid available while keeping unwanted gas out of the delivery path. The fuel inventory is separate from the shell’s dry mass, and the visible vessel volume does not establish usable propellant quantity.', 'pmd','valves'),
  section('operation','A shell is part of a fluid system','Pressure loads act through the vessel wall and into its fittings and supports. Internal management devices can use geometry and surface-tension effects to organize liquid delivery in low gravity; they are not visible from the outside. Fill state, temperature and acceleration history influence the fluid conditions. A supplier PMD tank is therefore more than a smooth sphere or cylinder with a port.','pmd'),
  section('engineering',oxidizer?'Compatibility comes before cosmetic material choice':'Material choice includes the complete wetted assembly',oxidizer?'Oxidizer compatibility must be assessed for the selected alloy, seals, joints and cleanliness condition, including everything wetted by the fluid. Titanium is inferred here from a cited all-titanium tank family, not established by a procurement drawing. Alloy, wall gauge, pressure life, inspection and attachment loads remain open. A gray surface should not be read as evidence that the tank has been qualified for the configured oxidizer.':'The cited tank family uses titanium, which supplies a defensible material-class analogy for the study shell. It does not establish the scaled vessel’s alloy, thickness or pressure rating. Fuel compatibility applies to welds, seals, internal devices and contaminants as well as the bulk wall. Supports must retain the vessel without damaging its pressure boundary, and joints need verification appropriate to the selected design.','pmd','structures')],
  [maker('Northrop Grumman','Titanium PMD tank families','Real vessel examples for studying shell and propellant-management integration. No catalog tank or pressure rating is selected here.','pmd'),maker('Moog','Propulsion valves and regulators','A reference for the connected feed components, not the manufacturer of this shell.','valves')],
  [alternative('Different vessel geometry','Can fit a different spacecraft envelope or packaging constraint.','Wall loads, supports, internal management and usable volume must be reassessed.','pmd'),alternative('Different propellant-management architecture','Can suit another fluid or mission acceleration environment.','The outlet behavior and residual usable inventory need new evidence.','pmd')],
  ['Inspect the shell’s attachment and its relationship to the other propellant vessel. Internal PMD geometry, wall thickness and pressure qualification are not resolved.'],
  [term('PMD','Propellant-management device: internal hardware that helps control liquid delivery.'),term('Wetted assembly','All parts and surfaces that contact the stored or flowing fluid.')],oxidizer?['flight:06.04','flight:06.03','flight:06.02','flight:06.05']:['flight:06.03','flight:06.04','flight:06.02','flight:06.05']);
}

topics.overwrap = article('pressurant-bottle-composite-overwrap',
 'The composite overwrap is a load-bearing fiber-and-resin structure around a pressure-vessel liner. In this study it represents one possible way to package the helium supply, rather than a documented supplier selection for the reference spacecraft.',[
 section('purpose','Storing pressurant in a light vessel','Pressurant gas supports the propulsion system’s pressure architecture and must be stored in a compatible vessel. A composite-overwrapped pressure vessel combines a liner with a structural wrap rather than relying on one thick metal wall alone. The liner and overwrap have different but interacting roles. Northrop’s product family includes both metal and composite-overwrapped vessels, so a carbon-fiber appearance should not be treated as the only available solution.','pressurant','copv'),
 section('operation','Fiber directions carry pressure loads','Pressure creates loads around the vessel and along its axis. Winding directions and the shape of the dome and bosses influence how those loads enter the composite. The liner contains the fluid and interacts mechanically with the wrap; its contribution depends on the actual design. A decorative crosshatch cannot reveal fiber angles, number of layers, resin, residual stresses or the load-sharing behavior of the finished vessel.','copv'),
 section('engineering','The vessel must be assessed as an assembly','Bosses, liner, composite, manufacturing process and supports need coordinated design and inspection. Temperature, pressure cycling, handling damage and time-dependent material behavior all affect the engineering assessment. The study leaves liner type, winding schedule and rating unresolved. It is therefore appropriate to use the model to inspect accommodation and connections while keeping qualification and service-life claims attached to an actual selected pressure-vessel design.','copv','structures')],
 [maker('Northrop Grumman','Pressurant tank families','A real comparison of metal and COPV options. The modeled carbon overwrap does not identify a specific product.','pressurant'),maker('NASA Engineering and Safety Center','COPV engineering reference','Explains why liner and overwrap behavior cannot be reduced to a simple external texture.','copv')],
 [alternative('All-metal pressure vessel','Uses a metallic wall as the principal pressure structure.','Mass, manufacture and pressure-life behavior differ from a COPV.','pressurant'),alternative('Another liner and winding architecture','Can address a different fluid, pressure or accommodation need.','Load sharing and manufacturing verification must be repeated for that construction.','copv')],
 ['Compare the bottle’s winding appearance with its end fittings and supports. The pattern is illustrative, not a manufacturing winding map or pressure certification.'],
 [term('COPV','Composite-overwrapped pressure vessel.'),term('Boss','A reinforced vessel fitting or opening that connects the pressure boundary to an interface.')],['flight:06.05','flight:06.02','flight:06.03','flight:06.04']);

export function materialKnowledge(record,catalog,hardware={}) {
 if(!record||record.category!=='flight'||record.massAccounting!=='included-in-parent')return null;
 const wbs=record.wbs||record.id.replace(/^flight:/,'');
 const kind=hardware?.energySystem?.thermal?.kind;
 switch(wbs){
  case '01.01.01': return coldPlate(hardware);
  case '01.01.02': return topics.boards;
  case '01.02.01': return topics.chassis;
  case '01.03.01': return topics.storage;
  case '01.04.01': return topics.network;
  case '02.01.01': return solarCells(record);
  case '02.01.02': return topics.coverglass;
  case '02.01.03': return topics.backing;
  case '02.01.04': return topics.boom;
  case '02.02.01': return topics.battery;
  case '02.03.01': return topics.pcdu;
  case '02.03.02': return topics.busbar;
  case '03.01.01': return radiatorFinish(record);
  case '03.01.02': return topics.radiatorFace;
  case '03.01.03': return topics.radiatorCore;
  case '03.01.04': return radiatorPassage(hardware);
  case '03.02.01': return kind==='passive-local'?topics.passive:kind==='heat-lift'?topics.heatPump:topics.coolant;
  case '03.02.02': return topics.heatLiftLines;
  case '03.03.01': return topics.mliAmber;
  case '03.03.02': return topics.mliWhite;
  case '03.03.03': return topics.mliInner;
  case '04.01.01': return topics.cmg;
  case '04.02.01': return topics.magCase;
  case '04.02.02': return topics.magWinding;
  case '04.03.01': return topics.starBaffle;
  case '05.01.01': return topics.patchFace;
  case '05.01.02': return rfContact(false);
  case '05.02.01': return topics.reflector;
  case '05.02.02': return rfContact(true);
  case '05.03.01': return topics.opticalSupport;
  case '05.03.02': return topics.opticalBaffle;
  case '05.03.03': return topics.opticalFinish;
  case '05.03.04': return topics.opticalAperture;
  case '06.01.01': return topics.nozzle;
  case '06.02.01': return topics.propFeed;
  case '06.03.01': return propellantTank(false);
  case '06.04.01': return propellantTank(true);
  case '06.05.01': return topics.overwrap;
  case '07.01.01': return topics.primaryFrame||null;
  case '07.01.02': return typeof launchAttachment==='function'?launchAttachment(false):null;
  case '07.02.01': return topics.structuralFace||null;
  case '07.02.02': return topics.feedthrough||null;
  case '07.02.03': return topics.structuralCore||null;
  case '07.03.01': return topics.shield||null;
  case '07.04.01': return topics.mechanism||null;
  case '07.05.01': return topics.harness||null;
  case '08.01.01': return topics.avionics;
  case '09.01.01': return typeof launchAttachment==='function'?launchAttachment(true):null;
  default:return null;
 }
}

topics.primaryFrame = article('primary-frame-and-tray-supports',
 'Longerons, transverse frames and tray supports form the core’s structural skeleton. They connect equipment loads to the spacecraft’s launch interface while preserving the geometry needed for mounting, deployment and operation.',[
 section('purpose','Giving every installed item a load path','Equipment has inertia during launch and must be restrained through a continuous series of supports and joints. Longitudinal members carry loads along the core, while transverse frames help maintain shape and distribute loads across it. Local tray supports connect payload equipment into that larger structure. The primary frame must therefore be designed around the actual mass locations and interfaces, not only the outside envelope.','structures','beyond-structures'),
 section('operation','Stiffness is different from strength','A member can remain unbroken yet deflect enough to disturb an optical alignment, overload a connector or allow nearby parts to touch. Structural design considers both load capacity and displacement, as well as vibration behavior. Joints determine how effectively separate members act together, so a strong-looking beam with a flexible connection can give a misleading impression. The model illustrates a structural arrangement rather than a verified finite-element solution.','structures'),
 section('engineering','Materials, manufacture and access','Machined aluminum, sheet assemblies and composite members offer different combinations of stiffness, mass, thermal expansion and fabrication effort. Mounting inserts and local reinforcements introduce concentrated equipment loads. The frame must also leave space for harnesses, plumbing, tools and the sequence of integration. Alloy, temper, joints and detailed dimensions remain part of a later structural definition; visible machining marks cannot supply them.','beyond-structures','anodize')],
 [maker('Beyond Gravity','Satellite structural products','Real examples of panels, struts, cylinders and inserts. They provide construction comparisons, not a selected core-frame product.','beyond-structures'),maker('NASA','Structures and mechanisms handbook','A system-level reference for evaluating architecture and manufacturing choices in context.','structures')],
 [alternative('Panel-dominated structure','Uses load-carrying panels to support equipment and stabilize the body.','Openings and concentrated attachments need careful reinforcement.','beyond-structures'),alternative('Composite primary members','Can tailor stiffness and expansion behavior.','Joints, inspection and thermal/electrical interfaces differ from metal framing.','structures')],
 ['Trace a tray or tank support into the main frame and onward to the launch attachment. Dense surface detail does not establish structural margin.'],
 [term('Longeron','A principal structural member running along a vehicle’s length.'),term('Load path','The connected route through which forces pass between parts.')],['flight:07.01','flight:01.02.01','flight:07.01.02','flight:07.02.01']);

function launchAttachment(lower) {
 return article(lower?'launch-side-adapter-fitting':'retained-spacecraft-attachment',
  lower?'The launch adapter and lower fitting connect the payload interface to the selected launch arrangement. They must carry launch loads and participate in a controlled release while matching the vehicle’s actual mechanical boundary.':'The retained spacecraft fittings connect the core structure to its launch attachment. Their defining feature is their place on the spacecraft side of the interface, so their structural role continues after release.',[
  section('purpose',lower?'Bridging payload and launch vehicle':'Giving the spacecraft a defined attachment',lower?'A launch interface must reconcile the payload’s mounting geometry with the launcher or cargo-support arrangement. An adapter can spread concentrated loads and create a repeatable mating boundary. The allocation may include a separable lower fitting, but the exact release ownership depends on the selected architecture. A conventional separation-ring example must not be mistaken for provider hardware in a study that uses a retained cargo carriage or another assumed installation.':'The spacecraft needs a repeatable mechanical boundary for integration, launch loading and release. Retained fittings pass loads into the primary structure while establishing positions and clearances at that boundary. They are different from ground handling fixtures and from launch-side hardware that does not accompany the spacecraft after separation. The details of that division belong to the selected launch-interface definition.','lightband','structures'),
  section('operation','Carrying loads before a controlled release','Before release, the interface transmits axial, lateral and bending loads between the payload and its support. During release, the mechanical restraint changes and any electrical connections crossing the boundary must behave as intended. The separation mechanism and the structural adapter have related but distinct functions. Catalog examples such as Lightband are useful for learning those interfaces, not for assuming that every modeled vehicle uses the same ring or release method.','lightband'),
  section('engineering','Interface drawings govern the details','Mounting patterns, datums, stiffness, fastener access and local reinforcement must agree on both sides. The allowed clearances and motion after release matter as much as static fit. Materials and finishes must preserve contact, bonding and load transfer while tolerating launch and temperature changes. The workbench’s metal allocation is not a released launcher interface control drawing, and it does not establish a verified separation impulse or shock level.','beyond-structures','structures')],
  [maker('Rocket Lab','Advanced Lightband','A real separation-system reference for studying mechanical and release interfaces. It is not asserted to be the selected device or size for this payload.','lightband'),maker('Beyond Gravity','Spacecraft structural interface products','A relevant construction comparison for adapters, panels and local attachments.','beyond-structures')],
  [alternative('Ring-style separation interface','Provides a defined circumferential attachment and release boundary.','The payload and launcher must match its allowed geometry and loads.','lightband'),alternative('Custom adapter or carriage interface','Can accommodate a different payload geometry or launch concept.','Requires its own structural, release and integration evidence.','structures')],
  [lower?'Inspect how the lower interface relates to the launch arrangement and the spacecraft attachment. The illustration does not certify a launcher-approved adapter.':'Follow the retained fitting into the spacecraft frame and compare it with the lower adapter. Retained hardware must not be counted again as a separate structural addition.'],
  [term('Interface control','The agreed dimensions, loads and functional requirements at a shared boundary.'),term('Retained hardware','Hardware that remains with the specified vehicle after an operation or separation.')],lower?['flight:09.01','flight:07.01.02','launch:vehicle']:['flight:07.01','flight:09.01','flight:09.01.01']);
}

topics.structuralFace = article('core-sandwich-face-sheets',
 'The structural face sheets form the skins of enclosure or equipment-support panels. They work with a lightweight core to provide stiffness and mounting surfaces without turning the whole panel volume into solid metal.',[
 section('purpose','A structural skin around the core','Panel skins can help stabilize a spacecraft structure and support equipment or outer coverings. Their function depends on how they connect to frames, adjacent panels and local fittings. In this study they are structural enclosure material, not evidence that the core is a pressure vessel. Radiator face sheets have an additional heat-rejection role and are documented separately because similar construction does not make the applications identical.','structures','beyond-structures'),
 section('operation','Separated skins resist bending','When a sandwich panel bends, one skin tends toward tension while the other tends toward compression. The core maintains separation and transfers load between them. This arrangement can provide useful stiffness with low mass, but its performance depends on intact bonds and properly introduced loads. An equipment mount or opening can require local reinforcement rather than simply drilling through a thin skin over hollow cells.','beyond-structures'),
 section('engineering','Designing a panel for its actual neighbors','Material, gauge, core construction and adhesive must be selected together. Cutouts for harnesses or access doors interrupt the load path and need analysis. Surface finish may also need to support thermal contact, electrical bonding or blanket attachment. Machined plates and stiffened sheet structures are legitimate alternatives where the panel’s interfaces or access requirements make a sandwich less attractive. The model does not identify a released panel layup or attachment pattern.','structures','anodize')],
 [maker('Beyond Gravity','Satellite sandwich panels and inserts','A real structural product comparison for skins, cores and equipment attachments; this is not a supplier selection for the enclosure.','beyond-structures')],
 [alternative('Machined or stiffened metal panel','Can integrate local bosses and access features without a bonded core.','Mass, stiffness and fabrication effort trade differently.','structures'),alternative('Composite face sheets','Can tailor in-plane stiffness and thermal expansion.','Joining, conductivity and through-thickness behavior need separate treatment.','beyond-structures')],
 ['Use an edge or inspection view to distinguish the skin from the core. An enclosure surface does not imply a sealed or pressurized internal atmosphere.'],
 [term('Sandwich panel','Two structural skins separated by a lightweight supporting core.'),term('Local reinforcement','Additional structure where a concentrated load or opening requires it.')],['flight:07.02','flight:07.02.03','flight:07.01.01','flight:03.01.02']);

topics.feedthrough = article('feedthrough-seals-and-insulators',
 'A feedthrough allows an electrical, optical or fluid connection to cross a physical boundary. Its insulating and sealing elements must match that boundary’s actual purpose; the word sealed does not mean the entire spacecraft core is pressurized.',[
 section('purpose','Preserving a boundary around a connection','A cable or tube passing through a panel creates more than a hole. The interface may need to retain the connection, prevent chafing, maintain electrical isolation or limit leakage where a real sealed boundary exists. Different locations require different combinations of those functions. The workbench groups unresolved seal and insulator details here without assigning one chemistry or one pressure-boundary role to every penetration.','feedthrough','harness'),
 section('operation','Isolation and sealing are separate requirements','An electrical insulator limits current between conductors or between a conductor and its housing. A seal limits passage of a fluid or gas under specified conditions. Ceramic-to-metal feedthroughs provide one real example that can combine these functions in a purpose-built assembly. A soft grommet, polymer connector insert and hermetic ceramic seal are not interchangeable simply because each may appear as a dark ring in a model.','feedthrough'),
 section('engineering','Matching the part to the interface','Temperature, voltage, mechanical movement, environment and any contacting fluid affect the choice. Differential expansion matters where unlike materials are joined; assembly loads must not crack a brittle insulator or damage a seal. A drawing would define mating dimensions, retention and the properties to verify. The current material remains unresolved, so the article identifies legitimate options without selecting an elastomer, ceramic or polymer from visual appearance.','structures','workmanship')],
 [maker('CeramTec','Ceramaseal feedthroughs','A real ceramic-to-metal component family for learning hermetic and insulating interfaces; it is not selected for these penetrations.','feedthrough'),maker('Glenair','Layered cable and connector references','Useful for distinguishing cable insulation from a boundary seal or connector insert.','harness','contacts')],
 [alternative('Hermetic ceramic-to-metal feedthrough','Can suit a boundary requiring both electrical isolation and controlled leakage.','Material joining and thermal expansion require a matched assembly.','feedthrough'),alternative('Connector or grommet at an unpressurized panel','Can provide retention, strain relief and abrasion protection without a hermetic boundary.','It should not be credited with pressure sealing or fluid compatibility it has not demonstrated.','harness')],
 ['Identify what actually crosses the panel and which boundary is being preserved. The dark placeholder does not establish a seal material or leak rating.'],
 [term('Hermetic','Designed to provide a specified very low leakage boundary.'),term('Strain relief','Support that prevents cable loads from concentrating at a termination.')],['flight:07.02','flight:07.05','flight:06.02','flight:02.03']);

topics.structuralCore = article('core-enclosure-sandwich-core',
 'The cellular core of a structural sandwich panel keeps its skins separated and supported. It creates stiffness efficiently while remaining mostly hidden in the finished spacecraft enclosure.',[
 section('purpose','Supporting thin structural skins','A thin sheet by itself can bend easily over a broad span. Separating two skins with a light core creates a deeper structural section without filling it with solid material. The core maintains that separation and helps the skins work together. Its location inside an enclosure panel distinguishes it from a radiator core, even when both use an aluminum honeycomb material class.','structures','beyond-structures'),
 section('operation','Loads enter through more than cell walls','The core transfers shear between skins and supports them against local deformation. Bond lines are essential to that behavior. At bolts, brackets and panel edges, inserts or closeouts spread concentrated forces into the sandwich instead of crushing unsupported cells. A visible hexagonal texture can illustrate the concept, but it does not show cell orientation, foil gauge, bond quality or the panel’s allowable loads.','beyond-structures'),
 section('engineering','Making the concealed volume manufacturable','Cell size, foil alloy, core thickness and adhesive affect the panel’s stiffness, mass and assembly process. Edges and penetrations need treatment appropriate to their mechanical and environmental roles; trapped volumes and vent paths must also be considered. Access openings can interrupt load transfer, so a panel’s layout is designed with its equipment and interfaces. The core is included in the parent panel allocation, not an extra independent mass added to a finished enclosure.','structures','act-radiator')],
 [maker('Beyond Gravity','Sandwich spacecraft structures','A real construction reference including panels and local interfaces; no particular core product is selected.','beyond-structures'),maker('Advanced Cooling Technologies','Bonded honeycomb-panel manufacturing','A related panel-manufacturing example, with radiator-specific functions that should not be assumed for this enclosure.','act-radiator')],
 [alternative('Foam core','Provides a different cellular support structure.','Mechanical, bonding and environmental properties need comparison for the intended panel.','redwire'),alternative('Rib-stiffened sheet construction','Creates stiffness through discrete structural features.','The load paths, access and manufacturing process differ from a bonded sandwich.','structures')],
 ['Look for an exposed panel edge if available. Most core material is concealed; it should not appear as honeycomb painted across the exterior skin.'],
 [term('Closeout','A detail that finishes or reinforces the edge of a sandwich panel.'),term('Bond line','The adhesive interface joining two parts.')],['flight:07.02.01','flight:07.02','flight:03.01.03']);

topics.shield = article('local-radiation-shield-liner',
 'A local radiation shield places material around selected electronics to change the particle environment that reaches them. Its effectiveness depends on the mission, surrounding structure and actual devices; no metal is a universal cure for space radiation.',[
 section('purpose','Protecting sensitive equipment selectively','Space electronics encounter effects that include accumulated dose and disturbances from individual particles. Shielding changes the environment reaching a component, while device selection and circuit or software architecture address how that component responds. Local shielding can concentrate added mass around sensitive equipment rather than increasing every external wall. The correct design begins with the orbit, mission duration and electronic susceptibility.','radiation','structures'),
 section('operation','The whole surrounding geometry matters','Particles approach from many directions and interact with the material they traverse. Existing equipment and structure already provide some shielding, while gaps and cable penetrations change the local environment. Additional material can also generate secondary radiation, so more thickness is not always a simple improvement. A useful analysis follows the environment through the actual surrounding materials rather than assigning a protection factor to a gray panel texture.','structures','radiation'),
 section('engineering','What the Juno example does and does not show','Juno’s titanium electronics vault is a real mission example of grouping electronics within a substantial shield. Its Jupiter environment and mission design are different from an orbital data center in Earth orbit. The titanium allocation here is an analogy, not evidence that the same thickness or protection is appropriate. Selecting a liner requires transport analysis, electronics test evidence and a mass trade; the current model does not resolve that shield geometry.','juno','radiation')],
 [maker('NASA JPL / Juno mission','Titanium electronics vault','A documented reference architecture, not a commercial shield product or proof of LEO performance.','juno'),maker('NASA','Electronics radiation-analysis resources','A primary starting point for connecting environment, shielding and component susceptibility.','radiation')],
 [alternative('Use existing structural shielding','Equipment placement can take advantage of material already carried by the spacecraft.','The shielding is directional and must be evaluated at the actual component location.','structures'),alternative('Spot or layered shielding','Can tailor protection around a particularly sensitive device.','Material sequence, secondary particles and added mass require analysis.','structures')],
 ['This allocation may have no separate geometry. Its absence from the rendered mesh does not justify inventing a completed vault or a shielding thickness.'],
 [term('TID','Total ionizing dose accumulated by a material or device.'),term('Single-event effect','A device response caused by an individual energetic particle.')],['flight:07.03','flight:01.01','flight:01.03','flight:08.01']);

topics.mechanism = article('deployment-drums-hinges-yokes-drives',
 'Deployment hardware changes the spacecraft from its compact launch arrangement to its operating geometry. Drums, hinges, yokes, restraints and drives have different jobs within that sequence, even when grouped under one mechanism allocation.',[
 section('purpose','Moving large appendages through a controlled sequence','Solar blankets and radiators may need to travel or rotate far beyond their stowed envelope. Launch restraints hold them during ascent; release devices remove those restraints; guides and hinges define motion; drives or stored energy provide it. A successful deployment also preserves cable routes and clearances. The high-detail model helps show that sequence but does not establish a supplier mechanism or a verified deployment reliability.','rosa','structures'),
 section('operation','Motion must preserve other interfaces','A hinge constrains relative motion around an intended axis, while a drum can organize stored material or a rollout path. A drive may supply controlled torque and position information. Rotating electrical connections can use an appropriate slip-ring or flex arrangement depending on travel and architecture. The Moog SADA datasheet is a useful real example of several such functions combined, not evidence that every workbench hinge contains that product.','sada'),
 section('engineering','The awkward details determine success','Bearing and joint behavior, alignment, harness stiffness, thermal distortion and interference all influence the required deployment effort. Launch loads may demand restraints much stronger than the deployed operating loads suggest. Lubrication, materials and surface treatments must suit the environment and intended life. Detailed textures or visible bolts do not establish release logic, torque margin, end stops or a verified clearance analysis for the full moving assembly.','structures','anodize')],
 [maker('Moog','Type 2 Solar Array Drive Assembly','A real combined drive and electrical-interface example; its ratings and size are not assigned to the modeled mechanisms.','sada'),maker('Redwire / NASA ROSA reference','Flexible-array deployment architecture','A relevant example of coordinated boom and blanket deployment rather than a universal mechanism recipe.','rosa','redwire')],
 [alternative('Stored-energy deployment','Can use the elastic behavior of a stowed structure to extend it.','Release, rate control and final configuration still need design and verification.','rosa'),alternative('Motor-driven deployment','Can provide commanded motion and position control.','Adds power, drive electronics and mechanism interfaces.','sada')],
 ['Use available deployment animation to examine the order of motion and potential interferences. Animation timing is illustrative, not a verified mechanism dynamic simulation.'],
 [term('Launch restraint','Hardware that holds a component in its stowed configuration during launch.'),term('Slip ring','An electrical connection designed to accommodate relative rotation.')],['flight:07.04','flight:02.01.04','flight:03.01','flight:07.05']);

topics.harness = article('power-and-data-harness-covering',
 'Harness covering protects and organizes the conductors linking spacecraft equipment. The visible wrap is only the outside of an assembly that may contain individual insulation, shields, twisted pairs, optical fibers and multiple termination types.',[
 section('purpose','Making electrical connections survivable','A spacecraft harness carries power, commands, measurements and data between units. Its coverings help maintain separation, protect against abrasion and preserve the intended routing. Clamps and strain relief prevent movement from concentrating loads at connectors. A visually tidy bundle is useful for accommodation, but it does not establish conductor sizing, signal quality or the material of every layer beneath its outer surface.','harness','workmanship'),
 section('operation','Different layers solve different problems','Conductor insulation prevents unintended electrical contact. A shield can control electromagnetic coupling when terminated as intended, while an outer jacket or wrap provides another mechanical or environmental boundary. Glenair’s SpaceWire cable drawing illustrates one actual construction with distinct conductor, insulation, shielding and jacket layers. It is a useful counterexample to assuming that every amber-looking cable has a polyimide outer jacket.','harness'),
 section('engineering','Routing is part of the design','Power conductors need acceptable voltage drop and temperature rise; data paths need suitable impedance, shielding and connector interfaces. Bends, branch points, moving joints and thermal expansion influence placement and restraint. Covering materials must match temperature, handling and environmental requirements. The workbench uses illustrative wrapping and sleeving to make routes understandable, while actual wire type, jacket chemistry, shield termination and workmanship remain component-specific choices.','contacts','workmanship')],
 [maker('Glenair','SpaceWire cable and connector specifications','Real layered interconnect examples for learning construction; they do not establish that every workbench route carries SpaceWire.','harness','contacts'),maker('NASA','Workmanship standards and training','A primary reference for cable, harness and termination practices that turn materials into a reliable assembly.','workmanship')],
 [alternative('Individual insulated wires with local sleeving','Can adapt to branching routes and varied electrical functions.','Bundle restraint and protection need attention throughout the route.','workmanship'),alternative('Rigid-flex or integrated interconnect','Can remove some cable and connector transitions within a unit.','Fabrication, bend constraints and repairability differ from a conventional harness.','ttm')],
 ['Follow branches into connectors and across moving interfaces. Rendered bundle diameter, wrap texture and routing are not a wire list or installation drawing.'],
 [term('Shield termination','The electrical connection of a cable shield at an interface.'),term('Bend allowance','Space needed to route a cable without exceeding its permissible curvature.')],['flight:07.05','flight:02.03.02','flight:01.04','flight:08.01','flight:07.04']);
